import { Q, W, indexBy } from './_helper.js';

const M = (n, title, qs, opts) => W('S7TA', 'tieng-anh', n, title, qs, opts);

export const S7TA_WEEKS = [
  // ──────────────── HK1 ────────────────
  M(1, 'Unit 1 — My Hobbies (Vocabulary)', [
    Q('"Hobby" means?', ['A meal', 'A daily duty (Một nhiệm vụ hằng ngày)', 'A school subject', 'An activity you do for pleasure'], 3, 'Hobby = sở thích, làm vì niềm vui.', ['Sai — \'a meal\' là bữa ăn, không phải sở thích.', 'Sai — nhiệm vụ hằng ngày là bổn phận, làm vì bắt buộc chứ không vì niềm vui.', 'Sai — \'a school subject\' là môn học, không phải sở thích.', 'Đúng — hobby là hoạt động làm vì niềm vui trong thời gian rảnh.']),
    Q('Which is a hobby?', ['Eating breakfast', 'Sleeping at night', 'Collecting stamps', 'Going to school'], 2, 'Collecting stamps là sở thích phổ biến.', ['Sai — ăn sáng là sinh hoạt hằng ngày, không phải sở thích.', 'Sai — ngủ ban đêm là nhu cầu cơ thể, không phải sở thích.', 'Đúng — sưu tầm tem (collecting stamps) là sở thích phổ biến.', 'Sai — đi học là việc bắt buộc, không phải sở thích.']),
    Q('"I ___ playing chess." → fill in.', ['enjoyed', 'enjoy', 'enjoying', 'enjoys'], 1, 'Present simple: I/you/we/they + V.', ['Sai — \'enjoyed\' là quá khứ, câu này nói sở thích chung nên dùng hiện tại đơn.', 'Đúng — hiện tại đơn với \'I\' giữ nguyên động từ: I enjoy.', 'Sai — \'enjoying\' là V-ing, thiếu trợ động từ be (am).', 'Sai — \'enjoys\' thêm -s chỉ dùng cho ngôi thứ ba số ít (he/she/it).']),
    Q('"He ___ photos in his free time." (take)', ['take (dùng cho I/you/we/they)', 'takes', 'taking (thiếu trợ động từ be)', 'is taking'], 1, 'He/She/It → V + s.', ['Sai — \'take\' dùng cho I/you/we/they, còn \'He\' cần thêm -s.', 'Đúng — ngôi thứ ba số ít He → động từ thêm -s: takes.', 'Sai — \'taking\' là V-ing, thiếu trợ động từ be và không hợp \'in his free time\'.', 'Sai — \'is taking\' là hiện tại tiếp diễn, không hợp với thói quen \'in his free time\'.']),
    Q('"Mountain climbing" is what kind of hobby?', ['Outdoor', 'Reading', 'Cooking', 'Indoor'], 0, 'Leo núi ngoài trời.', ['Đúng — leo núi là sở thích ngoài trời (outdoor).', 'Sai — \'reading\' là đọc sách, không liên quan leo núi.', 'Sai — \'cooking\' là nấu ăn, không phải leo núi.', 'Sai — leo núi diễn ra ngoài trời chứ không phải trong nhà (indoor).']),
    Q('"What hobby do you have?" — Best answer?', ['I like dancing.', 'I have two pens.', 'I live in Hanoi.', 'I am ten years old.'], 0, 'Sở thích: like + V-ing.', ['Đúng — câu hỏi về sở thích, trả lời \'I like dancing\' (like + V-ing).', 'Sai — đây là câu trả lời về đồ vật sở hữu, không phải sở thích.', 'Sai — đây là nơi sống, không trả lời câu hỏi về sở thích.', 'Sai — đây là tuổi tác, không trả lời câu hỏi về sở thích.']),
  ]),

  M(2, 'Unit 1 — Present simple vs Present continuous', [
    Q('Present simple is used for?', ['Habits and routines', 'Future plans', 'Finished actions yesterday', 'Actions happening right now'], 0, 'Thói quen, sự thật.', ['Đúng — hiện tại đơn diễn tả thói quen, lịch trình và sự thật hiển nhiên.', 'Sai — kế hoạch tương lai dùng will/be going to, không phải hiện tại đơn.', 'Sai — hành động đã kết thúc hôm qua dùng quá khứ đơn.', 'Sai — hành động đang xảy ra ngay lúc nói dùng hiện tại tiếp diễn.']),
    Q('Present continuous form is?', ['will + V', 'V + ed', 'am/is/are + V-ing', 'have + V3'], 2, 'be + V-ing.', ['Sai — \'will + V\' là cấu trúc tương lai đơn.', 'Sai — \'V + ed\' là quá khứ đơn (động từ có quy tắc).', 'Đúng — hiện tại tiếp diễn: am/is/are + V-ing.', 'Sai — \'have + V3\' là hiện tại hoàn thành.']),
    Q('"Look! She ___ a beautiful song." (sing)', ['sing (thiếu -s ở ngôi 3)', 'sings (hiện tại đơn, không hợp với Look!)', 'is singing', 'sang (quá khứ đơn, không hợp với Look!)'], 2, '"Look!" → đang xảy ra.', ['Sai — \'sing\' thiếu -s ở ngôi 3, và câu này cần thì tiếp diễn.', 'Sai — \'sings\' là hiện tại đơn (thói quen), không hợp tín hiệu \'Look!\'.', 'Đúng — \'Look!\' báo hành động đang diễn ra → hiện tại tiếp diễn: is singing.', 'Sai — \'sang\' là quá khứ đơn, không hợp với \'Look!\' chỉ hiện tại.']),
    Q('"My father ___ to work by bus every day." (go)', ['go (thiếu -es ở ngôi 3)', 'goes to (sai cấu trúc)', 'goes', 'is going'], 2, '"every day" → present simple, ngôi 3 +s.', ['Sai — \'go\' thiếu -es ở ngôi 3 số ít (my father).', 'Sai — thừa \'to\' vì sau đã có \'to work\'.', 'Đúng — \'every day\' báo thói quen → hiện tại đơn, ngôi 3 thêm -es: goes.', 'Sai — \'is going\' là tiếp diễn, không hợp với thói quen \'every day\'.']),
    Q('Time marker for present continuous?', ['last week', 'every day', 'now, at the moment, look!', 'yesterday'], 2, 'Tín hiệu hiện tại tiếp diễn.', ['Sai — \'last week\' là dấu hiệu quá khứ đơn.', 'Sai — \'every day\' là dấu hiệu hiện tại đơn (thói quen).', 'Đúng — now, at the moment, look! là tín hiệu của hiện tại tiếp diễn.', 'Sai — \'yesterday\' là dấu hiệu quá khứ đơn.']),
    Q('"I ___ a book now." (read)', ['am reading', 'reads (hiện tại đơn, không hợp now)', 'was reading', 'read (hiện tại đơn ngôi I, không hợp now)'], 0, '"now" → present continuous.', ['Đúng — \'now\' báo hành động đang diễn ra → hiện tại tiếp diễn: am reading.', 'Sai — \'reads\' là hiện tại đơn (lại sai ngôi), không hợp \'now\'.', 'Sai — \'was reading\' là quá khứ tiếp diễn, không hợp \'now\'.', 'Sai — \'read\' là hiện tại đơn (thói quen), không hợp với \'now\'.']),
  ]),

  M(3, 'Unit 2 — Health (Vocabulary)', [
    Q('"Toothache" means pain in?', ['Stomach', 'Eye (Mắt — eyeache không tự nhiên)', 'Tooth', 'Ear (Tai — đó là earache)'], 2, 'Tooth + ache = đau răng.', ['Sai — đau bụng/dạ dày là stomachache, không phải toothache.', 'Sai — đau mắt không gọi là eyeache, và toothache là về răng.', 'Đúng — tooth (răng) + ache (đau) = đau răng.', 'Sai — đau tai là earache, không phải toothache.']),
    Q('Which is healthy food?', ['Sweets', 'Fast food', 'Soft drinks', 'Vegetables and fruits'], 3, 'Rau và trái cây là healthy.', ['Sai — kẹo ngọt (sweets) nhiều đường, không tốt cho sức khỏe.', 'Sai — đồ ăn nhanh (fast food) nhiều dầu mỡ, không lành mạnh.', 'Sai — nước ngọt có ga (soft drinks) nhiều đường, không lành mạnh.', 'Đúng — rau và trái cây (vegetables and fruits) là thực phẩm lành mạnh.']),
    Q('"I have a ___." (đau đầu)', ['stomach', 'stomachache (đau bụng, không phải đau đầu)', 'headache', 'toothache (đau răng, không phải đau đầu)'], 2, 'Headache = đau đầu.', ['Sai — \'stomach\' là dạ dày (danh từ bộ phận), không phải tên bệnh đau đầu.', 'Sai — stomachache là đau bụng, không phải đau đầu.', 'Đúng — headache = đau đầu (head + ache).', 'Sai — toothache là đau răng, không phải đau đầu.']),
    Q('"You should drink more ___ every day."', ['water', 'soda (nước ngọt có ga, không tốt cho sức khỏe)', 'energy drinks (nước tăng lực, không nên uống nhiều)', 'coffee'], 0, 'Lời khuyên sức khoẻ phổ biến.', ['Đúng — lời khuyên sức khỏe phổ biến: nên uống nhiều nước hơn.', 'Sai — soda nhiều đường, không phải lời khuyên tốt cho sức khỏe.', 'Sai — nước tăng lực không nên uống nhiều, không hợp lời khuyên.', 'Sai — cà phê chứa caffeine, không phải lời khuyên uống nhiều cho học sinh.']),
    Q('Should + V là cấu trúc?', ['Asking permission', 'Future tense', 'Giving order', 'Giving advice'], 3, 'Should = nên (khuyên).', ['Sai — xin phép dùng May/Can, không phải should.', 'Sai — should không phải thì tương lai (đó là will).', 'Sai — ra lệnh dùng câu mệnh lệnh, không phải should.', 'Đúng — should + V dùng để khuyên bảo (nên làm gì).']),
    Q('"You ___ go to bed early." → khuyên đi ngủ sớm.', ['won\'t (sẽ không — phủ định tương lai)', 'shouldn\'t', 'should', 'will (sẽ — chỉ tương lai, không phải lời khuyên)'], 2, 'Should = nên.', ['Sai — won\'t là phủ định tương lai (sẽ không), không phải lời khuyên.', 'Sai — shouldn\'t là \'không nên\', ngược với ý khuyên đi ngủ sớm.', 'Đúng — should = nên, dùng để khuyên đi ngủ sớm.', 'Sai — will chỉ tương lai (sẽ), không phải lời khuyên.']),
  ]),

  M(4, 'Unit 2 — Modal verbs: should / shouldn\'t / must / mustn\'t', [
    Q('"You ___ eat too much sugar." (không nên)', ['should', 'can (có thể — chỉ khả năng, không phải lời khuyên)', 'shouldn\'t', 'must (bắt buộc — quá mạnh so với \'không nên\')'], 2, 'Shouldn\'t = không nên.', ['Sai — should là \'nên\', ngược với ý \'không nên\'.', 'Sai — can chỉ khả năng, không phải lời khuyên \'không nên\'.', 'Đúng — shouldn\'t = không nên, đúng với ý khuyên hạn chế đường.', 'Sai — must là \'bắt buộc\', quá mạnh và không hợp ý \'không nên\'.']),
    Q('"Students ___ wear uniforms at school." (bắt buộc)', ['should', 'may (có thể — xin phép, không phải bắt buộc)', 'must', 'can (có thể — chỉ khả năng, không phải bắt buộc)'], 2, 'Must = bắt buộc.', ['Sai — should chỉ là lời khuyên (nên), nhẹ hơn nghĩa \'bắt buộc\'.', 'Sai — may dùng để xin phép, không diễn tả sự bắt buộc.', 'Đúng — must = bắt buộc, đúng với quy định mặc đồng phục.', 'Sai — can chỉ khả năng/được phép, không phải bắt buộc.']),
    Q('"You ___ smoke here." (cấm)', ['shouldn\'t', 'must (bắt buộc làm, ngược nghĩa với \'cấm\')', 'should', 'mustn\'t'], 3, 'Mustn\'t = cấm tuyệt đối.', ['Sai — shouldn\'t là \'không nên\', nhẹ hơn nghĩa \'cấm\' tuyệt đối.', 'Sai — must là \'bắt buộc làm\', ngược nghĩa với \'cấm\'.', 'Sai — should là \'nên\', ngược với ý cấm.', 'Đúng — mustn\'t = cấm tuyệt đối, đúng với ý cấm hút thuốc.']),
    Q('"___ I open the window?" (xin phép)', ['Should', 'Must (bắt buộc — không hợp lời xin phép)', 'Will (sẽ — diễn tả tương lai, không xin phép)', 'May'], 3, 'May = xin phép lịch sự.', ['Sai — Should hỏi lời khuyên (có nên không), không phải xin phép.', 'Sai — Must là bắt buộc, không hợp lời xin phép.', 'Sai — Will diễn tả tương lai, không dùng để xin phép.', 'Đúng — May là cách xin phép lịch sự: May I open the window?']),
    Q('After modal verbs, we use?', ['to + V', 'bare infinitive (V)', 'V-ing (dạng tiếp diễn, sai sau modal)', 'V + ed'], 1, 'Modal + V nguyên thể không to.', ['Sai — sau modal không dùng \'to\' (sai: must to go).', 'Đúng — sau modal verb dùng động từ nguyên thể không to (bare infinitive).', 'Sai — sau modal không dùng V-ing.', 'Sai — sau modal không dùng V + ed (quá khứ).']),
    Q('"He can ___ English well." (speak)', ['speaking', 'speak', 'speaks', 'to speak'], 1, 'Can + V.', ['Sai — sau can không dùng V-ing (speaking).', 'Đúng — can + động từ nguyên thể không to: can speak.', 'Sai — sau can động từ không chia ngôi 3 (không speaks).', 'Sai — sau can không có \'to\' (không to speak).']),
  ]),

  M(5, 'Unit 3 — Community Service', [
    Q('"Community service" means?', ['Watching TV', 'Volunteer work to help the community', 'Doing homework', 'Going to a café'], 1, 'Hoạt động tình nguyện.', ['Sai — xem TV là giải trí cá nhân, không phải phục vụ cộng đồng.', 'Đúng — community service là công việc tình nguyện giúp đỡ cộng đồng.', 'Sai — làm bài tập là việc học cá nhân, không phải phục vụ cộng đồng.', 'Sai — đi quán cà phê là hoạt động cá nhân, không phải tình nguyện.']),
    Q('Which is a community service activity?', ['Eating dinner', 'Reading a novel', 'Playing video games', 'Cleaning the beach'], 3, 'Dọn bãi biển.', ['Sai — ăn tối là sinh hoạt cá nhân, không phải phục vụ cộng đồng.', 'Sai — đọc tiểu thuyết là sở thích cá nhân.', 'Sai — chơi điện tử là giải trí cá nhân.', 'Đúng — dọn bãi biển (cleaning the beach) là hoạt động tình nguyện vì cộng đồng.']),
    Q('"Volunteer" (n) means?', ['A student', 'A teacher', 'A doctor', 'A person who works without payment'], 3, 'Tình nguyện viên.', ['Sai — \'a student\' là học sinh/sinh viên, không phải tình nguyện viên.', 'Sai — \'a teacher\' là giáo viên, không phải tình nguyện viên.', 'Sai — \'a doctor\' là bác sĩ, không phải tình nguyện viên.', 'Đúng — volunteer là người làm việc không nhận lương (tình nguyện viên).']),
    Q('"We ___ books to poor children last month." (give) — past simple', ['are giving', 'will give', 'give (hiện tại đơn, sai vì có \'last month\')', 'gave'], 3, 'Past simple với "last month".', ['Sai — \'are giving\' là hiện tại tiếp diễn, không hợp \'last month\'.', 'Sai — \'will give\' là tương lai, ngược với \'last month\' (đã qua).', 'Sai — \'give\' là hiện tại đơn, không hợp dấu hiệu quá khứ \'last month\'.', 'Đúng — \'last month\' báo quá khứ → quá khứ đơn của give là gave.']),
    Q('"They ___ trees in the park yesterday." (plant)', ['plant (hiện tại đơn, sai vì có \'yesterday\')', 'planting', 'planted', 'plants'], 2, 'Yesterday → past simple, plant + ed.', ['Sai — \'plant\' là hiện tại đơn, không hợp dấu hiệu \'yesterday\'.', 'Sai — \'planting\' là V-ing, thiếu trợ động từ và sai thì.', 'Đúng — \'yesterday\' báo quá khứ → động từ có quy tắc thêm -ed: planted.', 'Sai — \'plants\' là hiện tại đơn ngôi 3, không hợp \'yesterday\'.']),
    Q('Past simple of irregular verb "go" is?', ['goed (sai vì go là bất quy tắc)', 'going (V-ing, không phải quá khứ)', 'gone (quá khứ phân từ, không phải V2)', 'went'], 3, 'go → went.', ['Sai — go là động từ bất quy tắc, không thêm -ed thành goed.', 'Sai — \'going\' là V-ing, không phải dạng quá khứ.', 'Sai — \'gone\' là quá khứ phân từ (V3), không phải quá khứ đơn (V2).', 'Đúng — go là bất quy tắc, quá khứ đơn là went.']),
  ]),

  M(6, 'Unit 3 — Past simple (regular & irregular verbs)', [
    Q('Past simple of "play" is?', ['plays (hiện tại đơn ngôi 3)', 'plaied', 'playing (V-ing, không phải quá khứ)', 'played'], 3, 'Regular: + ed.', ['Sai — \'plays\' là hiện tại đơn ngôi 3, không phải quá khứ.', 'Sai — play kết thúc bằng nguyên âm + y nên giữ y, không đổi thành plaied.', 'Sai — \'playing\' là V-ing, không phải quá khứ đơn.', 'Đúng — play là động từ có quy tắc, quá khứ thêm -ed: played.']),
    Q('Past simple of "study" is?', ['studyed (sai chính tả, không đổi y → i)', 'studyed', 'studyd', 'studied'], 3, 'y → i + ed: studied.', ['Sai — study kết thúc phụ âm + y phải đổi y → i, không viết studyed.', 'Sai — viết sai chính tả, đúng phải đổi y → i.', 'Sai — \'studyd\' không phải dạng đúng của study.', 'Đúng — phụ âm + y đổi thành i + ed: studied.']),
    Q('Past simple of "see" is?', ['saw', 'seen (quá khứ phân từ V3, không phải V2)', 'sees (hiện tại đơn ngôi 3)', 'saws (không phải dạng đúng của see)'], 0, 'Irregular: see → saw.', ['Đúng — see là bất quy tắc, quá khứ đơn là saw.', 'Sai — \'seen\' là quá khứ phân từ (V3), không phải quá khứ đơn (V2).', 'Sai — \'sees\' là hiện tại đơn ngôi 3, không phải quá khứ.', 'Sai — \'saws\' không phải dạng đúng của see.']),
    Q('Negative form: "She ___ help me." (không giúp)', ['doesn\'t', 'didn\'t', 'wasn\'t', 'isn\'t (be hiện tại, sai vì cần phủ định quá khứ)'], 1, 'Did + not + V.', ['Sai — doesn\'t là phủ định hiện tại đơn, không phải quá khứ.', 'Đúng — phủ định quá khứ đơn: didn\'t + V (She didn\'t help me).', 'Sai — wasn\'t là phủ định của be quá khứ, không dùng với động từ thường \'help\'.', 'Sai — isn\'t là be hiện tại, không hợp phủ định quá khứ.']),
    Q('Question: "___ they go to school yesterday?"', ['Does (hiện tại đơn ngôi 3, sai thì)', 'Are (be hiện tại, sai cấu trúc và thì)', 'Did', 'Do (hiện tại đơn, sai vì \'yesterday\')'], 2, 'Past → Did + S + V?', ['Sai — Does là hiện tại đơn ngôi 3, sai thì với \'yesterday\'.', 'Sai — Are là be hiện tại, không dùng với động từ thường \'go\'.', 'Đúng — câu hỏi quá khứ đơn: Did + S + V (Did they go...?).', 'Sai — Do là hiện tại đơn, không hợp dấu hiệu quá khứ \'yesterday\'.']),
    Q('Time markers for past simple?', ['yesterday, last week, ago, in 2020', 'now, today', 'usually', 'tomorrow, next week'], 0, 'Dấu hiệu quá khứ.', ['Đúng — yesterday, last week, ago, in 2020 đều là dấu hiệu quá khứ đơn.', 'Sai — now, today thiên về hiện tại, không phải dấu hiệu quá khứ.', 'Sai — usually là dấu hiệu hiện tại đơn (thói quen).', 'Sai — tomorrow, next week là dấu hiệu tương lai.']),
  ]),

  M(7, 'Unit 4 — Music and Arts', [
    Q('Which is a musical instrument?', ['Drum sticks (que đánh trống — không phải nhạc cụ)', 'Microphone stand (giá micro — phụ kiện, không phải nhạc cụ)', 'Pencil', 'Guitar'], 3, 'Guitar = đàn ghi-ta.', ['Sai — que đánh trống là dụng cụ phụ, bản thân nó không phải nhạc cụ.', 'Sai — giá micro là phụ kiện, không phải nhạc cụ.', 'Sai — bút chì (pencil) không liên quan âm nhạc.', 'Đúng — guitar (đàn ghi-ta) là một nhạc cụ.']),
    Q('"Painting" (n) is a kind of?', ['Performing art (nghệ thuật biểu diễn)', 'Folk craft (nghề thủ công dân gian)', 'Literature (văn học)', 'Visual art'], 3, 'Hội hoạ thuộc nghệ thuật thị giác.', ['Sai — nghệ thuật biểu diễn là múa, kịch, không phải hội họa.', 'Sai — nghề thủ công dân gian khác với hội họa.', 'Sai — văn học (literature) là chữ viết, không phải hội họa.', 'Đúng — painting (hội họa) thuộc nghệ thuật thị giác (visual art).']),
    Q('"I ___ to music every evening." (listen)', ['listens', 'listen', 'listening', 'listened'], 1, 'I + V (present simple).', ['Sai — \'listens\' thêm -s chỉ dùng cho ngôi 3, không dùng với I.', 'Đúng — hiện tại đơn với I giữ nguyên động từ: I listen.', 'Sai — \'listening\' là V-ing, thiếu trợ động từ be.', 'Sai — \'listened\' là quá khứ, không hợp thói quen \'every evening\'.']),
    Q('"Symphony" relates to?', ['Folk dance (múa dân gian — không phải symphony)', 'Rock music', 'Classical music', 'Pop music'], 2, 'Giao hưởng = cổ điển.', ['Sai — múa dân gian không liên quan giao hưởng.', 'Sai — nhạc rock không phải dòng giao hưởng.', 'Đúng — symphony (giao hưởng) thuộc nhạc cổ điển (classical music).', 'Sai — nhạc pop không phải giao hưởng.']),
    Q('"He can ___ the piano very well." (play)', ['to play', 'plays (hiện tại đơn ngôi 3, không dùng sau can)', 'play', 'playing'], 2, 'Modal can + V.', ['Sai — sau can không có \'to\' (không to play).', 'Sai — sau can động từ không chia ngôi 3 (không plays).', 'Đúng — modal can + động từ nguyên thể không to: can play.', 'Sai — sau can không dùng V-ing (playing).']),
    Q('"Folk song" means?', ['Rap music', 'Traditional song of the people', 'Classical concert', 'Modern dance'], 1, 'Dân ca = folk song.', ['Sai — rap là dòng nhạc hiện đại, không phải dân ca.', 'Đúng — folk song là bài hát truyền thống của dân gian (dân ca).', 'Sai — hòa nhạc cổ điển khác với dân ca.', 'Sai — múa hiện đại không phải dân ca.']),
  ]),

  M(8, 'Unit 4 — Comparative and Superlative adjectives', [
    Q('Comparative form of "tall"?', ['taller', 'more tall', 'tallor', 'tallest'], 0, 'Adj ngắn + er.', ['Đúng — tính từ ngắn so sánh hơn thêm -er: taller.', 'Sai — tính từ ngắn không dùng \'more\' (sai: more tall).', 'Sai — \'tallor\' viết sai chính tả, đúng là taller.', 'Sai — \'tallest\' là so sánh nhất, không phải so sánh hơn.']),
    Q('Superlative form of "good"?', ['best', 'better', 'goodest', 'gooder'], 0, 'Bất quy tắc: good → better → best.', ['Đúng — good là bất quy tắc, so sánh nhất là best.', 'Sai — \'better\' là so sánh hơn, không phải so sánh nhất.', 'Sai — good là bất quy tắc, không thêm -est thành goodest.', 'Sai — good là bất quy tắc, không thêm -er thành gooder.']),
    Q('Comparative of "beautiful"?', ['beautifuller', 'more beautiful', 'beautifulest', 'beautiful more'], 1, 'Adj dài: more + adj.', ['Sai — tính từ dài không thêm -er (sai: beautifuller).', 'Đúng — tính từ dài so sánh hơn dùng more + adj: more beautiful.', 'Sai — đó là dạng so sánh nhất sai, và tính từ dài không thêm -est.', 'Sai — sai trật tự từ, đúng là more beautiful.']),
    Q('"Mai is ___ than Lan." (young)', ['youngest', 'younger', 'more young', 'young (dạng nguyên, thiếu -er + than)'], 1, 'So sánh hơn: adj + er + than.', ['Sai — \'youngest\' là so sánh nhất, không đi với \'than\'.', 'Đúng — so sánh hơn tính từ ngắn: adj + er + than (younger than).', 'Sai — tính từ ngắn không dùng \'more\' (sai: more young).', 'Sai — \'young\' là dạng nguyên, thiếu -er khi có \'than\'.']),
    Q('"This is ___ song in the album." (good)', ['goodest', 'good (dạng nguyên, không phải so sánh nhất)', 'better', 'the best'], 3, 'Bất quy tắc + the (so sánh nhất).', ['Sai — good là bất quy tắc, không thêm -est thành goodest.', 'Sai — \'good\' là dạng nguyên, không phải so sánh nhất.', 'Sai — \'better\' là so sánh hơn, không phải so sánh nhất.', 'Đúng — good bất quy tắc, so sánh nhất là the best.']),
    Q('Structure of superlative for short adjectives?', ['adj + er', 'the most + adj', 'the + adj + est', 'adj + est'], 2, 'The + adj + est.', ['Sai — adj + er là so sánh hơn, không phải so sánh nhất.', 'Sai — the most + adj dùng cho tính từ dài, không phải tính từ ngắn.', 'Đúng — so sánh nhất tính từ ngắn: the + adj + est (the tallest).', 'Sai — thiếu mạo từ \'the\' (so sánh nhất phải có the).']),
  ]),

  M(9, 'Unit 5 — Vietnamese Food and Drink', [
    Q('"Phở" is what kind of food?', ['Italian pizza (Bánh pizza Ý)', 'Vietnamese noodle soup', 'Sandwich', 'Vegetable salad (Sa-lát rau)'], 1, 'Phở là món truyền thống Việt.', ['Sai — pizza là món Ý, không phải phở.', 'Đúng — phở là món súp mì truyền thống của Việt Nam (noodle soup).', 'Sai — sandwich là bánh kẹp, không phải phở.', 'Sai — sa-lát rau là món rau trộn, không phải phở.']),
    Q('Which is a Vietnamese drink?', ['Coffee from Brazil', 'Sugarcane juice (nước mía)', 'Tea from England', 'Coca-Cola'], 1, 'Nước mía rất phổ biến ở VN.', ['Sai — cà phê từ Brazil không phải đồ uống đặc trưng Việt Nam.', 'Đúng — nước mía (sugarcane juice) rất phổ biến ở Việt Nam.', 'Sai — trà Anh là đồ uống của Anh, không phải Việt Nam.', 'Sai — Coca-Cola là nước ngọt quốc tế, không phải của Việt Nam.']),
    Q('"How ___ rice do you need?" (uncountable noun)', ['few (dùng với danh từ đếm được số nhiều)', 'many (dùng với danh từ đếm được số nhiều)', 'some (dùng trong câu khẳng định, không phải hỏi \'how\')', 'much'], 3, '"Rice" không đếm được → much.', ['Sai — few dùng với danh từ đếm được số nhiều, còn rice không đếm được.', 'Sai — many dùng với danh từ đếm được số nhiều, không hợp rice.', 'Sai — some dùng trong câu khẳng định, không đi sau \'how\'.', 'Đúng — rice là danh từ không đếm được → dùng how much.']),
    Q('"How ___ apples are there?" (countable plural)', ['much (dùng với danh từ không đếm được)', 'an (mạo từ, không hợp \'how\')', 'many', 'a (mạo từ, không hợp \'how\' với số nhiều)'], 2, 'Đếm được số nhiều → many.', ['Sai — much dùng với danh từ không đếm được, còn apples đếm được.', 'Sai — \'an\' là mạo từ, không đi sau \'how\'.', 'Đúng — apples đếm được số nhiều → dùng how many.', 'Sai — \'a\' là mạo từ số ít, không hợp với danh từ số nhiều sau \'how\'.']),
    Q('Quantifier "a little" goes with?', ['Countable singular', 'Adjectives (tính từ, không đi với \'a little\')', 'Uncountable nouns', 'Countable plural'], 2, '"A little" + UC noun.', ['Sai — a little không đi với danh từ đếm được số ít.', 'Sai — a little không bổ nghĩa cho tính từ (đó là vai trò của trạng từ).', 'Đúng — a little đi với danh từ không đếm được (a little water).', 'Sai — danh từ đếm được số nhiều dùng \'a few\', không phải a little.']),
    Q('"A few" goes with?', ['Countable plural', 'Uncountable', 'Singular', 'Adjective (tính từ, không đi với \'a few\')'], 0, '"A few" + đếm được số nhiều.', ['Đúng — a few đi với danh từ đếm được số nhiều (a few apples).', 'Sai — danh từ không đếm được dùng \'a little\', không phải a few.', 'Sai — a few không đi với danh từ số ít.', 'Sai — a few không bổ nghĩa cho tính từ.']),
  ]),

  M(10, 'Unit 5 — Imperatives & Recipe instructions', [
    Q('Imperative form starts with?', ['V-ing (dạng -ing dùng cho danh động từ)', 'Bare verb (V)', 'V + ed', 'To + V'], 1, 'Mệnh lệnh: Open the book!', ['Sai — V-ing là danh động từ, không mở đầu câu mệnh lệnh.', 'Đúng — câu mệnh lệnh bắt đầu bằng động từ nguyên thể không to (Open!).', 'Sai — V + ed là quá khứ, không phải mệnh lệnh.', 'Sai — câu mệnh lệnh không có \'to\' trước động từ.']),
    Q('"___ the door, please." (mở)', ['Opens (hiện tại đơn ngôi 3, không phải mệnh lệnh)', 'Opening', 'Open', 'To open'], 2, 'Imperative + please cho lịch sự.', ['Sai — \'Opens\' là hiện tại đơn ngôi 3, không phải mệnh lệnh.', 'Sai — \'Opening\' là V-ing, không mở đầu câu mệnh lệnh.', 'Đúng — câu mệnh lệnh dùng động từ nguyên thể: Open the door, please.', 'Sai — câu mệnh lệnh không có \'to\' (không To open).']),
    Q('Negative imperative?', ['No + V', 'Not + V', 'Don\'t + V', 'Doesn\'t + V'], 2, 'Don\'t open the door!', ['Sai — không nói \'No + V\' để phủ định mệnh lệnh.', 'Sai — không nói \'Not + V\' để phủ định mệnh lệnh.', 'Đúng — mệnh lệnh phủ định: Don\'t + V (Don\'t open the door!).', 'Sai — không dùng Doesn\'t cho câu mệnh lệnh.']),
    Q('"First, ___ the rice." (rửa)', ['washes', 'washing', 'wash', 'washed'], 2, 'Imperative trong recipe.', ['Sai — \'washes\' là hiện tại đơn ngôi 3, không phải mệnh lệnh.', 'Sai — \'washing\' là V-ing, không mở đầu bước nấu ăn.', 'Đúng — công thức nấu ăn dùng mệnh lệnh: First, wash the rice.', 'Sai — \'washed\' là quá khứ, không phải mệnh lệnh.']),
    Q('"Then ___ the meat for 30 minutes." (chiên)', ['fries (hiện tại đơn ngôi 3, không phải mệnh lệnh)', 'fried (quá khứ, không phải mệnh lệnh)', 'fry', 'frying'], 2, 'Recipe step → imperative.', ['Sai — \'fries\' là hiện tại đơn ngôi 3, không phải mệnh lệnh.', 'Sai — \'fried\' là quá khứ, không phải mệnh lệnh.', 'Đúng — bước trong công thức dùng mệnh lệnh: Then fry the meat.', 'Sai — \'frying\' là V-ing, không mở đầu câu mệnh lệnh.']),
    Q('Sequence words for recipes?', ['First, then, next, finally', 'If, when', 'Because, so', 'And, or, but'], 0, 'Từ chỉ thứ tự.', ['Đúng — first, then, next, finally là từ chỉ thứ tự các bước.', 'Sai — if, when là liên từ điều kiện/thời gian, không chỉ thứ tự bước.', 'Sai — because, so chỉ nguyên nhân - kết quả, không phải thứ tự.', 'Sai — and, or, but là liên từ nối, không chỉ thứ tự các bước.']),
  ]),

  M(11, 'Unit 6 — The First University in Vietnam', [
    Q('"The first university in Vietnam" is?', ['Hanoi University', 'Văn Miếu – Quốc Tử Giám', 'Saigon University', 'Hue University'], 1, 'Quốc Tử Giám thành lập 1076.', ['Sai — Đại học Hà Nội là trường hiện đại, không phải trường đầu tiên.', 'Đúng — Văn Miếu – Quốc Tử Giám là trường đại học đầu tiên của Việt Nam (1076).', 'Sai — Đại học Sài Gòn là trường hiện đại, không phải trường đầu tiên.', 'Sai — Đại học Huế là trường hiện đại, không phải trường đầu tiên.']),
    Q('"Văn Miếu" was built to honor?', ['Kings only', 'Buddha', 'Soldiers', 'Confucius and scholars'], 3, 'Thờ Khổng Tử và các bậc hiền tài.', ['Sai — Văn Miếu không chỉ thờ vua, mà thờ Khổng Tử và bậc hiền tài.', 'Sai — Văn Miếu thờ Khổng Tử và học giả, không phải Phật (đó là chùa).', 'Sai — Văn Miếu không xây để tôn vinh binh lính.', 'Đúng — Văn Miếu được xây để thờ Khổng Tử và các bậc hiền tài (scholars).']),
    Q('Past simple of "build"?', ['build (nguyên mẫu, không phải V2)', 'builded', 'built', 'builts (không phải dạng đúng của build)'], 2, 'Irregular: build → built.', ['Sai — \'build\' là nguyên mẫu, không phải quá khứ đơn (V2).', 'Sai — build là bất quy tắc, không thêm -ed thành builded.', 'Đúng — build là bất quy tắc, quá khứ đơn là built.', 'Sai — \'builts\' không phải dạng đúng của build.']),
    Q('"It ___ in 1070." (build, passive)', ['is built', 'built (V2, thiếu trợ động từ bị động)', 'building', 'was built'], 3, 'Bị động quá khứ: was/were + V3.', ['Sai — \'is built\' là bị động hiện tại, không hợp năm 1070 (quá khứ).', 'Sai — \'built\' đứng một mình là chủ động, thiếu trợ động từ be để thành bị động.', 'Sai — \'building\' là V-ing, không phải bị động.', 'Đúng — bị động quá khứ: was/were + V3 (It was built in 1070).']),
    Q('Passive voice present simple form?', ['will be + V3', 'was/were + V3', 'have/has been + V3', 'am/is/are + V3'], 3, 'Hiện tại đơn bị động.', ['Sai — will be + V3 là bị động tương lai.', 'Sai — was/were + V3 là bị động quá khứ.', 'Sai — have/has been + V3 là bị động hiện tại hoàn thành.', 'Đúng — bị động hiện tại đơn: am/is/are + V3.']),
    Q('"Doctors ___ by people." (admire) — present passive', ['admires', 'admire', 'are admired', 'is admired'], 2, 'Doctors số nhiều → are + V3.', ['Sai — \'admires\' là chủ động, không phải bị động.', 'Sai — \'admire\' là chủ động, không phải bị động.', 'Đúng — Doctors số nhiều → bị động hiện tại: are + admired.', 'Sai — \'is admired\' dùng cho chủ ngữ số ít, còn Doctors số nhiều cần are.']),
  ]),

  M(12, 'Unit 6 — Passive voice (present simple)', [
    Q('Active: "People speak English everywhere." → Passive?', ['English are spoken everywhere.', 'English is spoken everywhere.', 'English speaks everywhere.', 'English was spoken everywhere.'], 1, 'Be + V3.', ['Sai — English là số ít nên dùng \'is\', không phải \'are\'.', 'Đúng — bị động hiện tại đơn: English is spoken everywhere (is + V3).', 'Sai — \'speaks\' là chủ động, không phải bị động.', 'Sai — \'was spoken\' là bị động quá khứ, không hợp ý hiện tại.']),
    Q('Passive of "She writes a letter"?', ['A letter are written by her.', 'A letter writes by her.', 'A letter was written by her.', 'A letter is written by her.'], 3, 'Singular → is + written.', ['Sai — \'a letter\' số ít nên dùng \'is\', không phải \'are\'.', 'Sai — \'writes\' là chủ động, không phải bị động.', 'Sai — \'was written\' là bị động quá khứ, còn câu gốc ở hiện tại.', 'Đúng — bị động hiện tại số ít: A letter is written by her.']),
    Q('"The cake ___ by Mai every Sunday." (make)', ['was made', 'making', 'makes (chủ động, không phải bị động)', 'is made'], 3, 'Every Sunday → present simple passive.', ['Sai — \'was made\' là bị động quá khứ, không hợp \'every Sunday\'.', 'Sai — \'making\' là V-ing, không phải bị động.', 'Sai — \'makes\' là chủ động, không phải bị động.', 'Đúng — \'every Sunday\' → bị động hiện tại đơn: is made.']),
    Q('In passive, the agent is introduced by?', ['of (giới từ sở hữu, không giới thiệu tác nhân)', 'from (chỉ nguồn gốc, không phải tác nhân)', 'by', 'with (chỉ công cụ, không phải tác nhân)'], 2, 'By + agent.', ['Sai — \'of\' chỉ sở hữu, không giới thiệu tác nhân trong câu bị động.', 'Sai — \'from\' chỉ nguồn gốc, không phải tác nhân.', 'Đúng — trong câu bị động, tác nhân được giới thiệu bằng \'by\'.', 'Sai — \'with\' chỉ công cụ/phương tiện, không phải tác nhân.']),
    Q('When to use passive?', ['In imperatives', 'When ordering', 'When asking questions', 'When the action is more important than the doer'], 3, 'Nhấn vào hành động/đối tượng.', ['Sai — câu mệnh lệnh không phải lý do dùng bị động.', 'Sai — ra lệnh không phải lý do dùng bị động.', 'Sai — đặt câu hỏi không phải lý do dùng bị động.', 'Đúng — dùng bị động khi hành động/đối tượng quan trọng hơn người thực hiện.']),
    Q('"Vietnamese ___ in Vietnam." (speak)', ['is speaking', 'was spoken', 'is spoken', 'speaks'], 2, 'Tiếng Việt được nói ở VN.', ['Sai — \'is speaking\' là tiếp diễn chủ động, không phải bị động.', 'Sai — \'was spoken\' là bị động quá khứ, không hợp sự thật hiện tại.', 'Đúng — bị động hiện tại đơn: Vietnamese is spoken in Vietnam.', 'Sai — \'speaks\' là chủ động, không phải bị động.']),
  ]),

  M(13, 'Unit 7 — Traffic (Vocabulary & signs)', [
    Q('A red traffic light means?', ['Stop', 'Slow down', 'Go (đèn xanh, không phải đèn đỏ)', 'Turn left'], 0, 'Đèn đỏ = dừng.', ['Đúng — đèn đỏ nghĩa là dừng lại (stop).', 'Sai — \'slow down\' (chậm lại) ứng với đèn vàng, không phải đèn đỏ.', 'Sai — \'go\' (đi) ứng với đèn xanh, không phải đèn đỏ.', 'Sai — đèn đỏ không có nghĩa rẽ trái.']),
    Q('"Pedestrian" means?', ['A passenger', 'A person walking on the street', 'A policeman', 'A driver'], 1, 'Người đi bộ.', ['Sai — passenger là hành khách (đi xe), không phải người đi bộ.', 'Đúng — pedestrian là người đi bộ trên đường.', 'Sai — policeman là cảnh sát, không phải người đi bộ.', 'Sai — driver là người lái xe, không phải người đi bộ.']),
    Q('You should walk on the ___ when crossing the street.', ['road (lòng đường — nguy hiểm cho người đi bộ)', 'zebra crossing', 'pavement', 'highway'], 1, 'Vạch sang đường.', ['Sai — đi giữa lòng đường (road) rất nguy hiểm cho người đi bộ.', 'Đúng — khi sang đường nên đi trên vạch kẻ (zebra crossing).', 'Sai — pavement là vỉa hè để đi dọc, không phải để băng qua đường.', 'Sai — highway là đường cao tốc, không dành cho người đi bộ băng qua.']),
    Q('"Helmet" must be worn when riding a?', ['Motorbike', 'Plane (máy bay — không yêu cầu helmet)', 'Boat (thuyền — không bắt buộc helmet)', 'Train (tàu hỏa — không cần helmet)'], 0, 'Đội mũ bảo hiểm khi đi xe máy.', ['Đúng — phải đội mũ bảo hiểm (helmet) khi đi xe máy (motorbike).', 'Sai — đi máy bay không cần đội mũ bảo hiểm.', 'Sai — đi thuyền không bắt buộc đội mũ bảo hiểm.', 'Sai — đi tàu hỏa không cần đội mũ bảo hiểm.']),
    Q('"No parking" sign means?', ['Don\'t park here', 'You can\'t stop here (Không được dừng tại đây)', 'Slow down', 'Park here'], 0, 'Cấm đỗ xe.', ['Đúng — \'No parking\' nghĩa là cấm đỗ xe ở đây.', 'Sai — cấm dừng là \'No stopping\', còn No parking chỉ cấm đỗ.', 'Sai — \'slow down\' là biển báo chậm lại, khác No parking.', 'Sai — ngược nghĩa, No parking là cấm đỗ chứ không phải mời đỗ.']),
    Q('Used to + V means?', ['A future plan', 'A finished action yesterday', 'A past habit that no longer happens', 'A present habit'], 2, 'Đã từng có thói quen trong quá khứ.', ['Sai — used to không diễn tả kế hoạch tương lai.', 'Sai — used to nói thói quen kéo dài trong quá khứ, không phải một hành động xảy ra hôm qua.', 'Đúng — used to + V diễn tả thói quen trong quá khứ nay không còn.', 'Sai — thói quen hiện tại dùng hiện tại đơn, không dùng used to.']),
  ]),

  M(14, 'Unit 7 — "It takes (sb) (time) to V"', [
    Q('"It takes me 20 minutes to ___ to school." (go)', ['going (V-ing, sai cấu trúc \'to V\')', 'goes (hiện tại đơn ngôi 3)', 'go', 'went (quá khứ, sai vì cần \'to + V\')'], 2, 'It takes + sb + time + to + V.', ['Sai — sau \'to\' phải là động từ nguyên thể, không dùng V-ing.', 'Sai — sau \'to\' không chia ngôi 3, không dùng goes.', 'Đúng — cấu trúc It takes + sb + time + to + V: to go.', 'Sai — sau \'to\' dùng nguyên thể, không dùng quá khứ went.']),
    Q('"How long ___ it take you to do homework?"', ['is (be, không dùng cho động từ thường \'take\')', 'does', 'are (be số nhiều, sai với \'it\')', 'do (trợ động từ, sai vì it cần does)'], 1, 'It takes → does it take.', ['Sai — \'take\' là động từ thường nên dùng trợ động từ does, không dùng be (is).', 'Đúng — chủ ngữ it ở hiện tại đơn dùng trợ động từ does: does it take.', 'Sai — \'are\' là be số nhiều, không hợp với chủ ngữ \'it\'.', 'Sai — chủ ngữ it ngôi 3 cần \'does\', không phải \'do\'.']),
    Q('"It takes my mother an hour to cook dinner." → câu hỏi how long?', ['How long is it take?', 'How long was it take?', 'How long does it take your mother to cook dinner?', 'How long do it take your mother to cook?'], 2, 'Form: How long does + S + take to V.', ['Sai — \'take\' là động từ thường, dùng does chứ không dùng be (is).', 'Sai — câu gốc ở hiện tại nên không dùng was, và take là động từ thường.', 'Đúng — How long does it take + sb + to V (đúng trợ động từ và cấu trúc).', 'Sai — chủ ngữ it cần \'does\', không phải \'do\'.']),
    Q('Distance question: "How ___ is it from your house to school?"', ['long (How long → hỏi thời gian/độ dài)', 'much (How much → hỏi giá/lượng)', 'many (How many → hỏi số lượng đếm được)', 'far'], 3, 'How far → khoảng cách.', ['Sai — How long hỏi thời gian/độ dài, không hỏi khoảng cách.', 'Sai — How much hỏi giá/lượng, không hỏi khoảng cách.', 'Sai — How many hỏi số lượng đếm được, không hỏi khoảng cách.', 'Đúng — hỏi khoảng cách dùng How far.']),
    Q('"It is about 2 ___ from my house to the city." (km)', ['metre (số ít, thiếu -s)', 'kilo (viết tắt không trang trọng, thiếu metre)', 'kilometre', 'kilometres'], 3, 'Số nhiều của km.', ['Sai — \'metre\' là mét và là số ít, không hợp \'2 km\'.', 'Sai — \'kilo\' là cách nói tắt, thiếu phần metre.', 'Sai — \'kilometre\' số ít, với số \'2\' cần số nhiều.', 'Đúng — với số nhiều (2) dùng kilometres.']),
    Q('Means of transport: "I go to school ___ bike."', ['in (dùng cho xe có khoang kín, không dùng cho bike)', 'on (dùng cho phương tiện cụ thể có \'a\': on a bike)', 'by', 'with (chỉ đi cùng ai, không phải phương tiện)'], 2, 'By + phương tiện (by bike, by bus).', ['Sai — \'in\' dùng cho xe có khoang (in a car), không dùng với bike chung chung.', 'Sai — \'on\' đi với \'a\' (on a bike), còn cấu trúc chung là by bike.', 'Đúng — phương tiện đi lại dùng by + N: by bike, by bus.', 'Sai — \'with\' chỉ đi cùng ai, không chỉ phương tiện.']),
  ]),

  M(15, 'Unit 8 — Films (Movies)', [
    Q('A "thriller" is a film that?', ['Makes you laugh', 'Makes you feel excited and tense', 'Tells a love story only', 'Teaches you science'], 1, 'Phim ly kì.', ['Sai — phim làm bạn cười là comedy (hài), không phải thriller.', 'Đúng — thriller (phim ly kỳ) làm người xem hồi hộp, căng thẳng.', 'Sai — phim chỉ kể chuyện tình là romance, không phải thriller.', 'Sai — phim dạy khoa học là documentary, không phải thriller.']),
    Q('"Comedy" makes you?', ['Cry (Khóc — đó là phim buồn/drama)', 'Laugh', 'Scared', 'Sleepy'], 1, 'Hài kịch.', ['Sai — làm bạn khóc là phim buồn/drama, không phải comedy.', 'Đúng — comedy (hài kịch) làm người xem cười (laugh).', 'Sai — làm bạn sợ là phim kinh dị (horror), không phải comedy.', 'Sai — buồn ngủ không phải đặc điểm của comedy.']),
    Q('"Cartoon" is a film for?', ['Only adults', 'Old people', 'Animals', 'Children mostly'], 3, 'Phim hoạt hình.', ['Sai — cartoon không chỉ dành riêng cho người lớn.', 'Sai — cartoon không phải làm cho người già.', 'Sai — cartoon dành cho người xem, không phải cho động vật.', 'Đúng — cartoon (phim hoạt hình) chủ yếu dành cho trẻ em.']),
    Q('"The film is so boring!" — boring means?', ['Very sad', 'Very funny', 'Very long', 'Not interesting'], 3, 'Chán = boring.', ['Sai — \'sad\' là buồn, khác với boring (chán).', 'Sai — \'funny\' là vui nhộn, ngược nghĩa với boring.', 'Sai — \'long\' là dài, không phải nghĩa của boring.', 'Đúng — boring nghĩa là chán, không thú vị (not interesting).']),
    Q('"The acting was excellent." → excellent means?', ['Average', 'Very good', 'Boring (Chán — ngược nghĩa)', 'Strange'], 1, 'Xuất sắc.', ['Sai — \'average\' là trung bình, không phải excellent.', 'Đúng — excellent nghĩa là xuất sắc (very good).', 'Sai — \'boring\' (chán) ngược nghĩa với excellent.', 'Sai — \'strange\' là kỳ lạ, không phải nghĩa xuất sắc.']),
    Q('"I have ___ that film three times." (see)', ['seeing', 'see (nguyên mẫu, sai sau \'have\')', 'saw (V2 quá khứ, sai sau \'have\')', 'seen'], 3, 'Present perfect: have + seen.', ['Sai — \'seeing\' là V-ing, không dùng trong hiện tại hoàn thành.', 'Sai — sau \'have\' dùng V3, không dùng nguyên mẫu see.', 'Sai — \'saw\' là V2 (quá khứ đơn), sau have phải là V3.', 'Đúng — hiện tại hoàn thành: have + seen (V3).']),
  ]),

  M(16, 'Unit 8 — Although / However / Connectors', [
    Q('"___ it rained heavily, we went out." (mặc dù)', ['Although', 'So (Vì vậy — chỉ kết quả)', 'And (Và — chỉ nối thêm, không tương phản)', 'Because'], 0, 'Although + clause = mặc dù.', ['Đúng — Although + mệnh đề diễn tả sự tương phản (mặc dù).', 'Sai — So chỉ kết quả (vì vậy), không hợp ý tương phản \'mặc dù\'.', 'Sai — And chỉ nối thêm, không diễn tả tương phản.', 'Sai — Because chỉ nguyên nhân (vì), không phải \'mặc dù\'.']),
    Q('"He is very smart. ___, he failed the test."', ['So (Vì vậy — chỉ kết quả, không tương phản)', 'However', 'Because', 'And (Và — chỉ nối thêm)'], 1, 'However = tuy nhiên (đầu câu mới).', ['Sai — So chỉ kết quả, không diễn tả tương phản giữa \'thông minh\' và \'trượt\'.', 'Đúng — However (tuy nhiên) đứng đầu câu mới, nối hai ý tương phản.', 'Sai — Because chỉ nguyên nhân, không hợp ý tương phản.', 'Sai — And chỉ nối thêm, không diễn tả tương phản.']),
    Q('"___ of the rain, we cancelled the trip." (vì)', ['But (Nhưng — liên từ tương phản, không đi với \'of\')', 'Because', 'Although', 'Because of'], 3, 'Because of + noun.', ['Sai — But là liên từ tương phản, không đi với \'of\'.', 'Sai — Because + mệnh đề (S+V), không đi với \'of + danh từ\'.', 'Sai — Although chỉ tương phản, không hợp ý nguyên nhân \'vì\'.', 'Đúng — Because of + danh từ (the rain) diễn tả nguyên nhân.']),
    Q('"Because" is followed by?', ['An adjective', 'A clause (S + V)', 'A noun phrase', 'An adverb'], 1, 'Because + S + V.', ['Sai — because không đi trực tiếp với tính từ.', 'Đúng — because theo sau là một mệnh đề (S + V).', 'Sai — cụm danh từ đi với \'because of\', không phải \'because\'.', 'Sai — because không theo sau bằng trạng từ.']),
    Q('"___ being tired, she kept working." (mặc dù)', ['However', 'Because', 'Despite', 'Although'], 2, 'Despite/In spite of + N/V-ing.', ['Sai — However đứng đầu câu mới, không đi trực tiếp với V-ing.', 'Sai — Because chỉ nguyên nhân và theo sau là mệnh đề, không phải V-ing.', 'Đúng — Despite + N/V-ing (despite being tired) diễn tả tương phản.', 'Sai — Although theo sau là mệnh đề (S+V), không phải V-ing.']),
    Q('"The film was long, ___ it was interesting."', ['so (vì vậy — chỉ kết quả, không tương phản)', 'but', 'because', 'or (hoặc — chỉ lựa chọn)'], 1, 'But = nhưng (tương phản nhẹ).', ['Sai — so chỉ kết quả, không diễn tả tương phản \'dài nhưng hay\'.', 'Đúng — but (nhưng) nối hai ý tương phản nhẹ.', 'Sai — because chỉ nguyên nhân, không hợp ý tương phản.', 'Sai — or chỉ sự lựa chọn (hoặc), không phải tương phản.']),
  ]),

  M(17, 'Review HK1 — Tenses overview', [
    Q('"I ___ TV every evening." (present simple)', ['am watching', 'watch', 'watches', 'watched'], 1, 'I + V.', ['Sai — \'am watching\' là tiếp diễn, không hợp thói quen \'every evening\'.', 'Đúng — hiện tại đơn với I giữ nguyên động từ: I watch.', 'Sai — \'watches\' thêm -s chỉ dùng cho ngôi 3, không dùng với I.', 'Sai — \'watched\' là quá khứ, không hợp thói quen hiện tại.']),
    Q('"She ___ to music now." (present continuous)', ['listens', 'listened', 'is listening', 'listen'], 2, 'Now → V-ing.', ['Sai — \'listens\' là hiện tại đơn, không hợp \'now\'.', 'Sai — \'listened\' là quá khứ, không hợp \'now\'.', 'Đúng — \'now\' báo hiện tại tiếp diễn: She is listening.', 'Sai — \'listen\' sai ngôi (cần -s) và sai thì với \'now\'.']),
    Q('"They ___ Hanoi last summer." (visit)', ['visit (hiện tại đơn, sai vì có \'last summer\')', 'visited', 'visits', 'are visiting'], 1, 'Last summer → past simple.', ['Sai — \'visit\' là hiện tại đơn, không hợp \'last summer\'.', 'Đúng — \'last summer\' báo quá khứ → visit + ed: visited.', 'Sai — \'visits\' là hiện tại đơn ngôi 3, không hợp dấu hiệu quá khứ.', 'Sai — \'are visiting\' là tiếp diễn, không hợp \'last summer\'.']),
    Q('"My brother ___ the guitar very well." (play)', ['played', 'play (thiếu -s ở ngôi 3 số ít)', 'plays', 'is playing'], 2, 'Habit + 3rd person.', ['Sai — \'played\' là quá khứ, còn đây là thói quen/khả năng hiện tại.', 'Sai — \'play\' thiếu -s ở ngôi 3 số ít (my brother).', 'Đúng — thói quen ngôi 3 số ít: plays.', 'Sai — \'is playing\' là tiếp diễn, không hợp thói quen chung.']),
    Q('Passive: "Rice ___ in Vietnam." (grow)', ['grew (quá khứ chủ động, không phải bị động)', 'grows (chủ động, không phải bị động)', 'was grown', 'is grown'], 3, 'Hiện tại đơn bị động.', ['Sai — \'grew\' là quá khứ chủ động, không phải bị động.', 'Sai — \'grows\' là chủ động, không phải bị động.', 'Sai — \'was grown\' là bị động quá khứ, không hợp sự thật hiện tại.', 'Đúng — bị động hiện tại đơn: Rice is grown in Vietnam.']),
    Q('Choose the best: "___ I help you?"', ['Will (sẽ — diễn tả tương lai, không lịch sự bằng May)', 'May', 'Should', 'Must (phải — quá bắt buộc, không lịch sự)'], 1, 'May = xin phép giúp đỡ lịch sự.', ['Sai — Will diễn tả tương lai, không lịch sự bằng May khi đề nghị giúp.', 'Đúng — May I help you? là cách đề nghị giúp đỡ lịch sự.', 'Sai — Should hỏi lời khuyên, không hợp ngữ cảnh đề nghị giúp đỡ.', 'Sai — Must mang nghĩa bắt buộc, quá mạnh và không lịch sự.']),
  ]),

  M(18, 'Final exam HK1 — Mixed', [
    Q('Comparative of "happy"?', ['happyer', 'happier', 'more happy', 'happiest'], 1, 'Adj 2 âm tiết kết thúc -y → -ier.', ['Sai — happy kết thúc -y phải đổi y → i, không viết happyer.', 'Đúng — tính từ 2 âm tiết kết thúc -y → -ier: happier.', 'Sai — tính từ kết thúc -y không dùng \'more\' (sai: more happy).', 'Sai — \'happiest\' là so sánh nhất, không phải so sánh hơn.']),
    Q('"Don\'t ___ here!" (smoke)', ['smokes', 'smoke', 'smoking', 'smoked'], 1, 'Don\'t + V.', ['Sai — sau Don\'t động từ không chia ngôi 3 (không smokes).', 'Đúng — mệnh lệnh phủ định: Don\'t + V nguyên thể (Don\'t smoke!).', 'Sai — sau Don\'t không dùng V-ing (smoking).', 'Sai — sau Don\'t không dùng quá khứ (smoked).']),
    Q('"How ___ sugar do we need?" (uncountable)', ['few (dùng với danh từ đếm được số nhiều)', 'much', 'many (dùng với danh từ đếm được số nhiều)', 'any (dùng trong câu hỏi yes/no, không hỏi lượng)'], 1, 'Much + UC.', ['Sai — few dùng với danh từ đếm được số nhiều, còn sugar không đếm được.', 'Đúng — sugar không đếm được → dùng how much.', 'Sai — many dùng với danh từ đếm được số nhiều, không hợp sugar.', 'Sai — any dùng trong câu hỏi yes/no, không dùng để hỏi lượng sau \'how\'.']),
    Q('Past of "buy"?', ['buyed (sai chính tả, buy là bất quy tắc)', 'buys (hiện tại đơn ngôi 3)', 'buyt (sai chính tả, không phải dạng đúng)', 'bought'], 3, 'Irregular: bought.', ['Sai — buy là bất quy tắc, không thêm -ed thành buyed.', 'Sai — \'buys\' là hiện tại đơn ngôi 3, không phải quá khứ.', 'Sai — \'buyt\' không phải dạng đúng của buy.', 'Đúng — buy là bất quy tắc, quá khứ đơn là bought.']),
    Q('"My school ___ in 1995." (build, passive)', ['was built', 'is building', 'built (V2 chủ động, thiếu trợ động từ be)', 'is built'], 0, 'Passive past simple.', ['Đúng — bị động quá khứ đơn: My school was built in 1995.', 'Sai — \'is building\' là tiếp diễn chủ động, không phải bị động quá khứ.', 'Sai — \'built\' đứng một mình là chủ động, thiếu trợ động từ be.', 'Sai — \'is built\' là bị động hiện tại, không hợp năm 1995 (quá khứ).']),
    Q('"___ she play tennis?" (does she chơi quần vợt không)', ['Does', 'Do (hiện tại đơn, sai vì ngôi 3 cần Does)', 'Did (quá khứ đơn, không phải hiện tại)', 'Is (be, không dùng cho động từ thường \'play\')'], 0, 'Present simple, ngôi 3 → Does + S + V.', ['Đúng — câu hỏi hiện tại đơn ngôi 3: Does + S + V (Does she play?).', 'Sai — ngôi 3 số ít she cần Does, không phải Do.', 'Sai — Did là quá khứ đơn, không hợp ý hiện tại.', 'Sai — Is là be, không dùng cho động từ thường \'play\'.']),
  ]),

  // ──────────────── HK2 ────────────────
  M(19, 'Unit 9 — Festivals around the World', [
    Q('"Christmas" is celebrated on?', ['January 1st', 'December 25th', 'October 31st', 'February 14th'], 1, 'Lễ Giáng Sinh 25/12.', ['Sai — 1/1 là Tết Dương lịch (New Year), không phải Giáng Sinh.', 'Đúng — lễ Giáng Sinh (Christmas) là ngày 25 tháng 12.', 'Sai — 31/10 là Halloween, không phải Giáng Sinh.', 'Sai — 14/2 là Valentine, không phải Giáng Sinh.']),
    Q('"Lunar New Year" in Vietnam is called?', ['Mid-Autumn', 'Hung Kings', 'National Day', 'Tet'], 3, 'Tết Nguyên đán.', ['Sai — Mid-Autumn là Tết Trung Thu, không phải Tết Nguyên đán.', 'Sai — Hung Kings là Giỗ Tổ Hùng Vương, không phải Tết âm lịch.', 'Sai — National Day là Quốc khánh, không phải Tết âm lịch.', 'Đúng — Tết âm lịch ở Việt Nam gọi là Tet (Tết Nguyên đán).']),
    Q('"Halloween" is associated with?', ['Christmas tree', 'Easter eggs', 'Pumpkins and costumes', 'Lanterns'], 2, 'Bí ngô và trang phục ma quỷ.', ['Sai — cây thông gắn với Giáng Sinh, không phải Halloween.', 'Sai — trứng Phục Sinh gắn với Easter, không phải Halloween.', 'Đúng — Halloween gắn với bí ngô (pumpkins) và trang phục hóa trang.', 'Sai — đèn lồng gắn với Trung Thu, không phải Halloween.']),
    Q('"Mid-Autumn Festival" in Vietnam is for?', ['Farmers only', 'Soldiers', 'Children', 'Doctors'], 2, 'Tết Trung Thu cho thiếu nhi.', ['Sai — Trung Thu không chỉ dành cho nông dân.', 'Sai — Trung Thu không phải lễ của binh lính.', 'Đúng — Tết Trung Thu chủ yếu dành cho trẻ em (children).', 'Sai — Trung Thu không phải lễ riêng của bác sĩ.']),
    Q('"Lantern" (n) means?', ['Quả bóng', 'Đèn lồng', 'Cái mũ', 'Cái trống'], 1, 'Đèn lồng — Trung Thu.', ['Sai — quả bóng là ball, không phải lantern.', 'Đúng — lantern nghĩa là đèn lồng (gắn với Trung Thu).', 'Sai — cái mũ là hat, không phải lantern.', 'Sai — cái trống là drum, không phải lantern.']),
    Q('Adverbs of manner often end in?', ['-ing', '-er', '-ed', '-ly'], 3, 'Quick → quickly.', ['Sai — đuôi -ing là V-ing/danh động từ, không phải trạng từ chỉ cách thức.', 'Sai — đuôi -er là so sánh hơn của tính từ, không phải trạng từ cách thức.', 'Sai — đuôi -ed là quá khứ/quá khứ phân từ, không phải trạng từ cách thức.', 'Đúng — trạng từ chỉ cách thức thường kết thúc -ly (quick → quickly).']),
  ]),

  M(20, 'Unit 9 — Adverbs of manner', [
    Q('Adverb form of "quick"?', ['quick (tính từ, không phải trạng từ)', 'quicker', 'quickness', 'quickly'], 3, 'Adj + ly.', ['Sai — \'quick\' là tính từ, không phải trạng từ.', 'Sai — \'quicker\' là so sánh hơn của tính từ, không phải trạng từ cách thức.', 'Sai — \'quickness\' là danh từ, không phải trạng từ.', 'Đúng — trạng từ cách thức = tính từ + ly: quickly.']),
    Q('"She sings ___." (beautiful)', ['beautifully', 'beautiful', 'beauty', 'more beautiful'], 0, 'Adv of manner.', ['Đúng — bổ nghĩa cho động từ sings cần trạng từ: beautifully.', 'Sai — \'beautiful\' là tính từ, không bổ nghĩa cho động từ.', 'Sai — \'beauty\' là danh từ, không bổ nghĩa cho động từ.', 'Sai — \'more beautiful\' là so sánh hơn của tính từ, không phải trạng từ.']),
    Q('Irregular adverb of "good" is?', ['best (so sánh nhất, không phải trạng từ thường)', 'better', 'goodly', 'well'], 3, 'good → well.', ['Sai — \'best\' là so sánh nhất, không phải trạng từ thường của good.', 'Sai — \'better\' là so sánh hơn, không phải dạng trạng từ thường.', 'Sai — \'goodly\' không phải trạng từ đúng của good.', 'Đúng — trạng từ bất quy tắc của good là well.']),
    Q('"He runs very ___." (fast)', ['fastly', 'fast', 'faster', 'fastest'], 1, '"Fast" vừa là adj vừa là adv.', ['Sai — không có dạng \'fastly\', fast giữ nguyên khi làm trạng từ.', 'Đúng — \'fast\' vừa là tính từ vừa là trạng từ, giữ nguyên: runs fast.', 'Sai — \'faster\' là so sánh hơn, không hợp khi chỉ nói cách chạy.', 'Sai — \'fastest\' là so sánh nhất, không hợp ngữ cảnh.']),
    Q('Position of adverb of manner is usually?', ['Before the verb always', 'At the beginning', 'Before the subject', 'After the main verb / after object'], 3, 'Sau V hoặc sau tân ngữ.', ['Sai — trạng từ cách thức không luôn đứng trước động từ.', 'Sai — trạng từ cách thức thường không đứng đầu câu.', 'Sai — trạng từ cách thức không đứng trước chủ ngữ.', 'Đúng — trạng từ cách thức thường đứng sau động từ hoặc sau tân ngữ.']),
    Q('"They worked ___." (chăm chỉ)', ['hard', 'harder', 'hardly', 'hardest'], 0, 'Hard = chăm chỉ; hardly = hầu như không.', ['Đúng — \'hard\' nghĩa là chăm chỉ và là trạng từ: worked hard.', 'Sai — \'harder\' là so sánh hơn, không hợp khi chỉ nói chăm chỉ.', 'Sai — \'hardly\' nghĩa là hầu như không, ngược ý chăm chỉ.', 'Sai — \'hardest\' là so sánh nhất, không hợp ngữ cảnh.']),
  ]),

  M(21, 'Unit 10 — Sources of Energy', [
    Q('Renewable energy includes?', ['Plastic', 'Solar, wind, water', 'Coal, oil, gas', 'Wood, paper'], 1, 'Năng lượng tái tạo.', ['Sai — nhựa (plastic) không phải nguồn năng lượng tái tạo.', 'Đúng — năng lượng tái tạo gồm mặt trời, gió, nước (solar, wind, water).', 'Sai — than, dầu, khí là năng lượng hóa thạch không tái tạo.', 'Sai — gỗ, giấy không phải nhóm năng lượng tái tạo điển hình.']),
    Q('Non-renewable energy?', ['Water (Thủy điện — tái tạo)', 'Solar (Năng lượng mặt trời — tái tạo)', 'Coal and oil', 'Wind (Năng lượng gió — tái tạo)'], 2, 'Hoá thạch không tái tạo.', ['Sai — thủy điện (water) là năng lượng tái tạo.', 'Sai — năng lượng mặt trời (solar) là năng lượng tái tạo.', 'Đúng — than và dầu (coal and oil) là năng lượng hóa thạch không tái tạo.', 'Sai — năng lượng gió (wind) là năng lượng tái tạo.']),
    Q('"Solar energy" comes from?', ['Coal (Than đá — đó là năng lượng hóa thạch)', 'Water (Nước — đó là thủy điện)', 'The sun', 'The wind'], 2, 'Năng lượng mặt trời.', ['Sai — than đá tạo năng lượng hóa thạch, không phải năng lượng mặt trời.', 'Sai — nước tạo thủy điện, không phải năng lượng mặt trời.', 'Đúng — solar energy đến từ mặt trời (the sun).', 'Sai — gió tạo năng lượng gió, không phải năng lượng mặt trời.']),
    Q('Future simple form?', ['am/is/are + V-ing', 'going to + V', 'have + V3', 'will + V'], 3, 'Will + bare V.', ['Sai — am/is/are + V-ing là hiện tại tiếp diễn.', 'Sai — be going to + V diễn tả kế hoạch, không phải tương lai đơn.', 'Sai — have + V3 là hiện tại hoàn thành.', 'Đúng — tương lai đơn: will + động từ nguyên thể.']),
    Q('"Tomorrow, I ___ visit my grandparents."', ['do (trợ động từ hiện tại, không phải tương lai)', 'will', 'did (quá khứ, ngược với \'Tomorrow\')', 'am (be, không phải tương lai đơn)'], 1, 'Tomorrow → will.', ['Sai — \'do\' là trợ động từ hiện tại, không phải tương lai.', 'Đúng — \'Tomorrow\' báo tương lai → will + V (will visit).', 'Sai — \'did\' là quá khứ, ngược với dấu hiệu \'Tomorrow\'.', 'Sai — \'am\' là be, không tạo tương lai đơn với \'visit\'.']),
    Q('"They ___ run out of oil in the future." (might)', ['mighting', 'might', 'mights', 'to might'], 1, 'Might + V (có thể).', ['Sai — might là modal, không có dạng -ing (mighting).', 'Đúng — might + V nguyên thể diễn tả khả năng (có thể).', 'Sai — modal might không chia ngôi 3 (không mights).', 'Sai — might không đi với \'to\' (không to might).']),
  ]),

  M(22, 'Nghỉ Tết — Light review', [
    Q('"Tet" is celebrated in?', ['Vietnam', 'China (Trung Quốc — họ có Lunar New Year riêng)', 'England', 'France'], 0, 'Tết Việt Nam.', ['Đúng — Tet (Tết Nguyên đán) là lễ tết của Việt Nam.', 'Sai — Trung Quốc có Lunar New Year riêng, không gọi là Tet.', 'Sai — nước Anh không ăn Tết Nguyên đán.', 'Sai — nước Pháp không ăn Tết Nguyên đán.']),
    Q('"Happy New Year!" means?', ['Cảm ơn!', 'Chúc mừng năm mới!', 'Tạm biệt!', 'Chào buổi sáng!'], 1, 'Lời chúc đầu năm.', ['Sai — \'Cảm ơn\' là Thank you, không phải Happy New Year.', 'Đúng — Happy New Year nghĩa là Chúc mừng năm mới.', 'Sai — \'Tạm biệt\' là Goodbye, không phải Happy New Year.', 'Sai — \'Chào buổi sáng\' là Good morning, không phải Happy New Year.']),
    Q('Past of "see"?', ['saw', 'sees (hiện tại đơn ngôi 3)', 'seen (quá khứ phân từ V3)', 'seed (sai vì see là bất quy tắc)'], 0, 'Irregular.', ['Đúng — see là bất quy tắc, quá khứ đơn là saw.', 'Sai — \'sees\' là hiện tại đơn ngôi 3, không phải quá khứ.', 'Sai — \'seen\' là quá khứ phân từ (V3), không phải quá khứ đơn (V2).', 'Sai — see là bất quy tắc, không thêm -ed thành seed.']),
    Q('Adverb of "slow"?', ['slowless', 'slowness', 'slowily (sai chính tả, thừa chữ i)', 'slowly'], 3, 'Slow → slowly.', ['Sai — \'slowless\' không phải dạng trạng từ đúng.', 'Sai — \'slowness\' là danh từ, không phải trạng từ.', 'Sai — viết sai chính tả, thừa chữ i (đúng là slowly).', 'Đúng — trạng từ của slow là slowly (adj + ly).']),
    Q('Comparative of "big"?', ['biger (sai vì thiếu gấp đôi phụ âm cuối)', 'more big', 'bigger', 'bigest'], 2, 'Phụ âm + nguyên âm + phụ âm: gấp đôi phụ âm cuối + er.', ['Sai — big phải gấp đôi phụ âm cuối, không viết biger.', 'Sai — big là tính từ ngắn, không dùng \'more\'.', 'Đúng — big (phụ âm-nguyên âm-phụ âm) gấp đôi g + er: bigger.', 'Sai — \'bigest\' là so sánh nhất sai chính tả, không phải so sánh hơn.']),
    Q('"I ___ very tired now." (be)', ['am', 'be (nguyên mẫu, chưa chia)', 'is (dùng cho he/she/it)', 'are (dùng cho you/we/they)'], 0, 'I + am.', ['Đúng — chủ ngữ I đi với am: I am tired.', 'Sai — \'be\' là dạng nguyên mẫu chưa chia.', 'Sai — \'is\' dùng cho he/she/it, không dùng với I.', 'Sai — \'are\' dùng cho you/we/they, không dùng với I.']),
  ]),

  M(23, 'Unit 10 — Future simple (will / won\'t)', [
    Q('"I think it ___ rain tomorrow." (will)', ['do (trợ động từ hiện tại, không phải tương lai)', 'won\'t (sẽ không — ngược nghĩa với dự đoán có mưa)', 'is (be, không phải tương lai đơn)', 'will'], 3, 'Will + V.', ['Sai — \'do\' là trợ động từ hiện tại, không phải tương lai.', 'Sai — \'won\'t\' là sẽ không, ngược với dự đoán \'sẽ mưa\'.', 'Sai — \'is\' là be, không tạo tương lai đơn với \'rain\'.', 'Đúng — dự đoán tương lai (tomorrow): will rain.']),
    Q('Negative of "will" is?', ['don\'t (phủ định hiện tại đơn, không phải tương lai)', 'doesn\'t', 'won\'t (will not)', 'didn\'t'], 2, 'Will not = won\'t.', ['Sai — \'don\'t\' là phủ định hiện tại đơn, không phải tương lai.', 'Sai — \'doesn\'t\' là phủ định hiện tại đơn ngôi 3.', 'Đúng — phủ định của will là won\'t (will not).', 'Sai — \'didn\'t\' là phủ định quá khứ đơn.']),
    Q('Question: "___ they come to the party?"', ['Do (hiện tại đơn, không phải tương lai)', 'Will', 'Are (be hiện tại, không phải tương lai đơn)', 'Did (quá khứ đơn, không phải tương lai)'], 1, 'Will + S + V?', ['Sai — Do là hiện tại đơn, không tạo câu hỏi tương lai.', 'Đúng — câu hỏi tương lai đơn: Will + S + V (Will they come?).', 'Sai — Are là be hiện tại, không tạo tương lai đơn với \'come\'.', 'Sai — Did là quá khứ đơn, không phải tương lai.']),
    Q('Future time markers?', ['every day', 'tomorrow, next week, in 2050', 'now, at the moment', 'yesterday, last year'], 1, 'Dấu hiệu tương lai.', ['Sai — every day là dấu hiệu hiện tại đơn (thói quen).', 'Đúng — tomorrow, next week, in 2050 là dấu hiệu tương lai.', 'Sai — now, at the moment là dấu hiệu hiện tại tiếp diễn.', 'Sai — yesterday, last year là dấu hiệu quá khứ.']),
    Q('"By 2050, robots ___ many jobs." (do)', ['are doing', 'did (quá khứ, sai vì \'By 2050\' là tương lai)', 'do (hiện tại đơn, sai vì \'By 2050\' là tương lai)', 'will do'], 3, '"By 2050" → tương lai.', ['Sai — \'are doing\' là hiện tại tiếp diễn, không hợp \'By 2050\'.', 'Sai — \'did\' là quá khứ, ngược với \'By 2050\' (tương lai).', 'Sai — \'do\' là hiện tại đơn, không hợp \'By 2050\' (tương lai).', 'Đúng — \'By 2050\' báo tương lai → will do.']),
    Q('"I ___ help you with your homework." (offer)', ['will', 'did (quá khứ, không phải lời đề nghị tương lai)', 'do (hiện tại đơn, không phải đề nghị tương lai)', 'am (be, không dùng với \'help\')'], 0, 'Offer = will.', ['Đúng — đề nghị giúp đỡ ngay lúc nói dùng will: I will help you.', 'Sai — \'did\' là quá khứ, không phải lời đề nghị tương lai.', 'Sai — \'do\' là hiện tại đơn, không diễn tả lời đề nghị.', 'Sai — \'am\' là be, không đi với động từ thường \'help\'.']),
  ]),

  M(24, 'Unit 11 — Travelling in the Future', [
    Q('"Means of transport" includes?', ['Food, drink', 'Houses, schools', 'Cars, bikes, trains, planes', 'Books, pens, rulers (Sách, bút, thước — đồ học tập)'], 2, 'Phương tiện đi lại.', ['Sai — đồ ăn, đồ uống không phải phương tiện đi lại.', 'Sai — nhà, trường là công trình, không phải phương tiện đi lại.', 'Đúng — phương tiện đi lại gồm xe hơi, xe đạp, tàu, máy bay.', 'Sai — sách, bút, thước là đồ học tập, không phải phương tiện.']),
    Q('"Driverless car" means?', ['A car for one person', 'A small car', 'A car without a driver', 'An old car'], 2, 'Xe tự lái.', ['Sai — driverless không có nghĩa là xe một chỗ ngồi.', 'Sai — driverless không có nghĩa là xe nhỏ.', 'Đúng — driverless car là xe không có người lái (xe tự lái).', 'Sai — driverless không có nghĩa là xe cũ.']),
    Q('"In the future, people ___ to Mars." (travel)', ['will travel', 'are travelling', 'travelled', 'travel'], 0, 'Future simple.', ['Đúng — \'in the future\' báo tương lai đơn: will travel.', 'Sai — \'are travelling\' là hiện tại tiếp diễn, không hợp tương lai.', 'Sai — \'travelled\' là quá khứ, ngược với \'in the future\'.', 'Sai — \'travel\' là hiện tại đơn, không hợp \'in the future\'.']),
    Q('"Hyperloop" is a fast?', ['Transport tube system', 'Boat (Thuyền — phương tiện chậm trên nước)', 'Bicycle', 'Plane (Máy bay — phương tiện hàng không)'], 0, 'Hệ thống đường ống tốc độ cao.', ['Đúng — Hyperloop là hệ thống ống vận chuyển tốc độ cao.', 'Sai — thuyền là phương tiện chậm trên nước, không phải Hyperloop.', 'Sai — xe đạp không phải hệ thống tốc độ cao.', 'Sai — máy bay là phương tiện hàng không, không phải Hyperloop.']),
    Q('"Eco-friendly" vehicles are?', ['Polluting (Gây ô nhiễm — ngược nghĩa)', 'Expensive', 'Good for the environment', 'Heavy (Nặng — không liên quan môi trường)'], 2, 'Thân thiện môi trường.', ['Sai — gây ô nhiễm ngược nghĩa với eco-friendly.', 'Sai — eco-friendly nói về môi trường, không phải về giá đắt.', 'Đúng — eco-friendly nghĩa là thân thiện, tốt cho môi trường.', 'Sai — \'nặng\' không liên quan tới nghĩa thân thiện môi trường.']),
    Q('Future plan with "be going to" structure?', ['have + V3', 'will + V', 'am/is/are + going to + V', 'V + ed'], 2, 'Be + going to + V.', ['Sai — have + V3 là hiện tại hoàn thành.', 'Sai — will + V là tương lai đơn, không phải cấu trúc be going to.', 'Đúng — kế hoạch tương lai: am/is/are + going to + V.', 'Sai — V + ed là quá khứ đơn.']),
  ]),

  M(25, 'Unit 11 — Going to + V for future plans', [
    Q('"I ___ visit my uncle this weekend." (going to)', ['are going to', 'will going to', 'is going to', 'am going to'], 3, 'I am going to + V.', ['Sai — \'are\' dùng cho you/we/they, không dùng với I.', 'Sai — không kết hợp will với going to (sai: will going to).', 'Sai — \'is\' dùng cho he/she/it, không dùng với I.', 'Đúng — chủ ngữ I → am going to + V.']),
    Q('"She ___ travel to Japan next month."', ['is going to', 'will going to', 'are going to', 'am going to'], 0, 'She → is.', ['Đúng — chủ ngữ She → is going to + V.', 'Sai — không kết hợp will với going to.', 'Sai — \'are\' dùng cho số nhiều, không dùng với She.', 'Sai — \'am\' chỉ dùng với I, không dùng với She.']),
    Q('Negative: "We ___ stay home."', ['don\'t going to', 'aren\'t going to', 'won\'t going to', 'isn\'t going to'], 1, 'We are not = aren\'t.', ['Sai — cấu trúc going to dùng be, không dùng don\'t.', 'Đúng — We + are not + going to = aren\'t going to.', 'Sai — không kết hợp won\'t với going to.', 'Sai — \'isn\'t\' dùng cho số ít, không dùng với We.']),
    Q('Question: "___ you going to study tonight?"', ['Will (tương lai đơn với V, không kèm going to)', 'Is (be số ít, sai với \'you\')', 'Are', 'Do (trợ động từ, không dùng với \'going to\')'], 2, 'Are + S + going to + V?', ['Sai — Will dùng cho tương lai đơn (will + V), không đi với going to.', 'Sai — Is là be số ít, không hợp với \'you\'.', 'Đúng — câu hỏi be going to: Are + S + going to + V.', 'Sai — Do là trợ động từ thường, không dùng với going to.']),
    Q('"Be going to" expresses?', ['Past events', 'Plans or intentions', 'Habits', 'Permission'], 1, 'Kế hoạch/dự định.', ['Sai — sự việc quá khứ dùng quá khứ đơn, không phải be going to.', 'Đúng — be going to diễn tả kế hoạch hoặc dự định.', 'Sai — thói quen dùng hiện tại đơn, không phải be going to.', 'Sai — xin phép dùng May/Can, không phải be going to.']),
    Q('"Look at those clouds! It ___ rain." (going to)', ['is going to', 'is go to', 'goes to', 'will (dự đoán không bằng chứng, ở đây có dấu hiệu rõ)'], 0, 'Dấu hiệu hiện tại → going to (prediction with evidence).', ['Đúng — có dấu hiệu rõ (mây) → dự đoán dùng is going to rain.', 'Sai — \'is go to\' sai cấu trúc, đúng là is going to.', 'Sai — \'goes to\' không phải cấu trúc be going to.', 'Sai — will dùng cho dự đoán không có bằng chứng, ở đây có dấu hiệu rõ.']),
  ]),

  M(26, 'Unit 12 — An Overcrowded World', [
    Q('"Overcrowded" means?', ['Too many people in a place', 'Comfortable', 'Peaceful (Yên bình — ngược nghĩa)', 'Spacious (Rộng rãi — ngược nghĩa)'], 0, 'Quá đông đúc.', ['Đúng — overcrowded nghĩa là quá đông người ở một nơi.', 'Sai — \'comfortable\' là thoải mái, không phải nghĩa quá đông.', 'Sai — \'peaceful\' (yên bình) ngược nghĩa với đông đúc.', 'Sai — \'spacious\' (rộng rãi) ngược nghĩa với quá đông.']),
    Q('Effects of overpopulation include?', ['More fresh water', 'Better life only', 'Pollution, lack of housing, traffic jams', 'More forests'], 2, 'Tác động tiêu cực.', ['Sai — quá đông dân không làm tăng nước sạch.', 'Sai — quá đông dân không chỉ mang lại cuộc sống tốt hơn.', 'Đúng — quá đông dân gây ô nhiễm, thiếu nhà ở, tắc đường.', 'Sai — quá đông dân thường làm giảm rừng, không tăng rừng.']),
    Q('"Megacity" is a city with?', ['Less than 1 million', 'About 100,000 people', '50,000 people', 'More than 10 million people'], 3, 'Siêu đô thị.', ['Sai — dưới 1 triệu người chưa phải siêu đô thị.', 'Sai — khoảng 100.000 người là thành phố nhỏ.', 'Sai — 50.000 người là thị trấn/đô thị nhỏ.', 'Đúng — megacity (siêu đô thị) có hơn 10 triệu dân.']),
    Q('"___ ever been to a big city?" (Have you)', ['Do you', 'Are you', 'Have you', 'Did you'], 2, 'Present perfect: Have + S + V3.', ['Sai — \'Do you\' là hiện tại đơn, không đi với \'ever been\'.', 'Sai — \'Are you\' là be, không tạo hiện tại hoàn thành.', 'Đúng — hiện tại hoàn thành: Have you ever been...?', 'Sai — \'Did you\' là quá khứ đơn, không đi với \'been\' (V3).']),
    Q('Present perfect form?', ['have/has + V3', 'am/is/are + V-ing', 'was/were + V3', 'will + V'], 0, 'Have + V3.', ['Đúng — hiện tại hoàn thành: have/has + V3.', 'Sai — am/is/are + V-ing là hiện tại tiếp diễn.', 'Sai — was/were + V3 là bị động quá khứ.', 'Sai — will + V là tương lai đơn.']),
    Q('"She ___ in this city for 5 years." (live)', ['lived (quá khứ đơn, không hợp \'for 5 years\' tới hiện tại)', 'has lived', 'lives (hiện tại đơn, không diễn tả quãng thời gian kéo dài)', 'is living'], 1, 'For 5 years → present perfect.', ['Sai — \'lived\' là quá khứ đơn, không diễn tả việc kéo dài tới hiện tại.', 'Đúng — \'for 5 years\' (tới hiện tại) → hiện tại hoàn thành: has lived.', 'Sai — \'lives\' là hiện tại đơn, không diễn tả quãng thời gian kéo dài.', 'Sai — \'is living\' là tiếp diễn, không hợp \'for 5 years\' kéo dài tới nay.']),
  ]),

  M(27, 'Unit 12 — Present perfect', [
    Q('Present perfect of "go"?', ['have goed', 'have gone', 'have went', 'have going'], 1, 'go → gone (V3).', ['Sai — go là bất quy tắc, không thêm -ed thành goed.', 'Đúng — hiện tại hoàn thành: have + gone (V3 của go là gone).', 'Sai — \'went\' là V2 (quá khứ đơn), sau have phải là V3.', 'Sai — \'going\' là V-ing, không phải V3.']),
    Q('"I ___ this film twice." (see)', ['have seen', 'am seeing', 'saw (quá khứ đơn, không diễn tả kinh nghiệm)', 'see (hiện tại đơn, không kèm số lần kinh nghiệm)'], 0, 'Twice → present perfect (kinh nghiệm).', ['Đúng — \'twice\' chỉ kinh nghiệm → hiện tại hoàn thành: have seen.', 'Sai — \'am seeing\' là tiếp diễn, không diễn tả kinh nghiệm.', 'Sai — \'saw\' là quá khứ đơn, không diễn tả kinh nghiệm tới hiện tại.', 'Sai — \'see\' là hiện tại đơn, không hợp khi nói số lần kinh nghiệm.']),
    Q('Time markers for present perfect?', ['yesterday, ago', 'now (dùng cho hiện tại tiếp diễn)', 'ever, never, just, already, yet, since, for', 'tomorrow, next week'], 2, 'Đặc trưng present perfect.', ['Sai — yesterday, ago là dấu hiệu quá khứ đơn.', 'Sai — now là dấu hiệu hiện tại tiếp diễn.', 'Đúng — ever, never, just, already, yet, since, for là dấu hiệu hiện tại hoàn thành.', 'Sai — tomorrow, next week là dấu hiệu tương lai.']),
    Q('"He has ___ his homework." (finish)', ['finishing', 'finishes', 'finish', 'finished'], 3, 'Has + V3.', ['Sai — \'finishing\' là V-ing, không dùng sau has.', 'Sai — \'finishes\' là hiện tại đơn, không dùng sau has.', 'Sai — \'finish\' là nguyên thể, sau has phải là V3.', 'Đúng — hiện tại hoàn thành: has + finished (V3).']),
    Q('"___ you ever ___ to Hue?" (be)', ['Did / be', 'Are / been', 'Have / been', 'Do / be'], 2, 'Have + S + ever + been.', ['Sai — \'Did / be\' là quá khứ và sai dạng (cần V3 been).', 'Sai — \'Are\' không tạo hiện tại hoàn thành dù \'been\' đúng.', 'Đúng — Have + S + ever + been (hiện tại hoàn thành hỏi kinh nghiệm).', 'Sai — \'Do / be\' là hiện tại đơn và sai dạng động từ.']),
    Q('Negative: "I ___ him for years." (not see)', ['am not seeing', 'don\'t see', 'haven\'t seen', 'didn\'t see'], 2, 'Haven\'t + V3.', ['Sai — \'am not seeing\' là tiếp diễn, không hợp \'for years\' tới hiện tại.', 'Sai — \'don\'t see\' là hiện tại đơn, không diễn tả việc kéo dài.', 'Đúng — \'for years\' tới hiện tại → phủ định hiện tại hoàn thành: haven\'t seen.', 'Sai — \'didn\'t see\' là quá khứ đơn, không diễn tả kéo dài tới nay.']),
  ]),

  M(28, 'Conditional Type 1 (real future)', [
    Q('Conditional type 1 form?', ['If + S + V-ing', 'If + S + had + V3, S + would have + V3', 'If + S + V2, S + would + V', 'If + S + V (present), S + will + V'], 3, 'Real condition: if + present, will + V.', ['Sai — câu điều kiện không dùng \'If + S + V-ing\'.', 'Sai — đó là cấu trúc câu điều kiện loại 3 (quá khứ không có thật).', 'Sai — đó là cấu trúc câu điều kiện loại 2 (hiện tại không có thật).', 'Đúng — điều kiện loại 1: If + hiện tại đơn, S + will + V.']),
    Q('"If it ___ tomorrow, we will stay home." (rain)', ['rained', 'will rain', 'rains', 'rain (thiếu -s ở ngôi 3 số ít \'it\')'], 2, 'If clause = present simple.', ['Sai — \'rained\' là quá khứ, không dùng trong mệnh đề if loại 1.', 'Sai — mệnh đề if loại 1 không dùng will, mà dùng hiện tại đơn.', 'Đúng — mệnh đề if loại 1 dùng hiện tại đơn, ngôi 3 it → rains.', 'Sai — \'rain\' thiếu -s ở ngôi 3 số ít (it).']),
    Q('"If you study hard, you ___ pass the test." (will)', ['would (loại 2, không phải loại 1 thực tế)', 'will', 'are (be, không phải tương lai đơn)', 'have (trợ động từ hoàn thành, sai cấu trúc)'], 1, 'Main clause = will + V.', ['Sai — \'would\' dùng cho điều kiện loại 2, không phải loại 1.', 'Đúng — mệnh đề chính điều kiện loại 1: will + V (will pass).', 'Sai — \'are\' là be, không tạo tương lai đơn với \'pass\'.', 'Sai — \'have\' là trợ động từ hoàn thành, sai cấu trúc loại 1.']),
    Q('"If she ___ early, she will catch the bus." (leave)', ['will leave', 'leaves', 'leave (thiếu -s ở ngôi 3 số ít)', 'left (quá khứ đơn, không phải cond. 1)'], 1, 'Ngôi 3 → leaves.', ['Sai — mệnh đề if loại 1 không dùng will.', 'Đúng — mệnh đề if loại 1 dùng hiện tại đơn, ngôi 3 she → leaves.', 'Sai — \'leave\' thiếu -s ở ngôi 3 số ít (she).', 'Sai — \'left\' là quá khứ, không dùng trong điều kiện loại 1.']),
    Q('We use conditional type 1 for?', ['Present unreal', 'Past unreal', 'Real or possible situations in the future', 'Impossible situations'], 2, 'Tình huống có khả năng xảy ra.', ['Sai — tình huống hiện tại không có thật dùng loại 2.', 'Sai — tình huống quá khứ không có thật dùng loại 3.', 'Đúng — loại 1 dùng cho tình huống có thật/có thể xảy ra ở tương lai.', 'Sai — tình huống không thể xảy ra dùng loại 2/3, không phải loại 1.']),
    Q('"If we don\'t save energy, we ___ run out of it." (will)', ['wouldn\'t', 'won\'t (sẽ không — ngược nghĩa với hậu quả \'cạn kiệt\')', 'will', 'would (loại 2, không phải loại 1 thực tế)'], 2, 'Hậu quả tương lai.', ['Sai — \'wouldn\'t\' thuộc loại 2 và mang nghĩa phủ định.', 'Sai — \'won\'t\' là sẽ không, ngược với hậu quả \'sẽ cạn kiệt\'.', 'Đúng — mệnh đề chính loại 1 nêu hậu quả tương lai: will run out.', 'Sai — \'would\' dùng cho điều kiện loại 2, không phải loại 1.']),
  ]),

  M(29, 'Vocabulary review — Environment & Society', [
    Q('"Pollution" means?', ['Khí trời', 'Sự sạch sẽ', 'Sự ô nhiễm', 'Mặt trời'], 2, 'Ô nhiễm.', ['Sai — \'khí trời\' không phải nghĩa của pollution.', 'Sai — \'sự sạch sẽ\' ngược nghĩa với pollution.', 'Đúng — pollution nghĩa là sự ô nhiễm.', 'Sai — \'mặt trời\' là the sun, không phải pollution.']),
    Q('"Recycle" means?', ['Mua mới', 'Đốt rác', 'Tái chế', 'Bỏ rác'], 2, 'Re + cycle.', ['Sai — \'mua mới\' không phải nghĩa của recycle.', 'Sai — \'đốt rác\' là burn, không phải tái chế.', 'Đúng — recycle nghĩa là tái chế (re + cycle).', 'Sai — \'bỏ rác\' là throw away, không phải recycle.']),
    Q('"Reduce" means?', ['Tái chế (đó là recycle)', 'Tái sử dụng (đó là reuse)', 'Giảm', 'Sản xuất (đó là produce)'], 2, 'Reduce = giảm.', ['Sai — tái chế là recycle, không phải reduce.', 'Sai — tái sử dụng là reuse, không phải reduce.', 'Đúng — reduce nghĩa là giảm.', 'Sai — sản xuất là produce, không phải reduce.']),
    Q('"Reuse" means?', ['Tái sử dụng', 'Tái chế (đó là recycle, không phải reuse)', 'Mua lại', 'Cho đi'], 0, 'Re + use.', ['Đúng — reuse nghĩa là tái sử dụng (re + use).', 'Sai — tái chế là recycle, không phải reuse.', 'Sai — \'mua lại\' không phải nghĩa của reuse.', 'Sai — \'cho đi\' là give away, không phải reuse.']),
    Q('"Plant trees" helps?', ['Reduce pollution and CO2', 'Increase traffic', 'Make noise', 'Waste water'], 0, 'Trồng cây tốt cho môi trường.', ['Đúng — trồng cây giúp giảm ô nhiễm và CO2.', 'Sai — trồng cây không làm tăng giao thông.', 'Sai — trồng cây không gây tiếng ồn.', 'Sai — trồng cây không gây lãng phí nước.']),
    Q('"Save water" means?', ['Đổ nước', 'Lưu nước', 'Tiết kiệm nước', 'Mua nước'], 2, 'Save = tiết kiệm.', ['Sai — \'đổ nước\' là pour, ngược ý tiết kiệm.', 'Sai — save water ở đây nghĩa tiết kiệm, không phải lưu trữ.', 'Đúng — save water nghĩa là tiết kiệm nước.', 'Sai — \'mua nước\' là buy water, không phải save water.']),
  ]),

  M(30, 'Reading skill — Identifying main idea & details', [
    Q('When skimming a text, you should?', ['Memorize the whole text', 'Translate every sentence', 'Read every word slowly', 'Read quickly for the main idea'], 3, 'Skim = đọc lướt.', ['Sai — skim không phải học thuộc toàn bộ văn bản.', 'Sai — skim không phải dịch từng câu.', 'Sai — skim không đọc chậm từng từ (đó ngược với đọc lướt).', 'Đúng — skim là đọc lướt nhanh để nắm ý chính.']),
    Q('Scanning is used for?', ['Counting words', 'Reading for pleasure', 'Finding specific information (names, dates, numbers)', 'Translating word by word'], 2, 'Scan = quét tìm chi tiết.', ['Sai — scan không phải đếm số từ.', 'Sai — scan không phải đọc để giải trí.', 'Đúng — scan là quét nhanh để tìm thông tin cụ thể (tên, ngày, số).', 'Sai — scan không phải dịch từng từ.']),
    Q('A topic sentence often appears?', ['At the beginning of a paragraph', 'In every sentence', 'Always at the end', 'In the middle only'], 0, 'Câu chủ đề thường đầu đoạn.', ['Đúng — câu chủ đề thường nằm ở đầu đoạn văn.', 'Sai — không phải mọi câu đều là câu chủ đề.', 'Sai — câu chủ đề không nhất thiết luôn ở cuối.', 'Sai — câu chủ đề không chỉ nằm ở giữa đoạn.']),
    Q('Context clues help you?', ['Translate exactly', 'Guess meanings of unknown words', 'Count syllables', 'Pronounce correctly'], 1, 'Đoán nghĩa qua ngữ cảnh.', ['Sai — manh mối ngữ cảnh không dùng để dịch chính xác từng chữ.', 'Đúng — context clues giúp đoán nghĩa từ chưa biết qua ngữ cảnh.', 'Sai — manh mối ngữ cảnh không dùng để đếm âm tiết.', 'Sai — manh mối ngữ cảnh không giúp phát âm.']),
    Q('Before reading, you should?', ['Translate the whole text', 'Skip the title', 'Read the last paragraph first', 'Look at title, pictures, headings'], 3, 'Pre-reading strategy.', ['Sai — không cần dịch cả văn bản trước khi đọc.', 'Sai — không nên bỏ qua tiêu đề (tiêu đề rất quan trọng).', 'Sai — không nên đọc đoạn cuối trước.', 'Đúng — trước khi đọc nên xem tiêu đề, hình ảnh, đề mục.']),
    Q('After reading, you should?', ['Read aloud once more only', 'Forget it immediately', 'Summarize the main idea', 'Translate again'], 2, 'Củng cố hiểu.', ['Sai — đọc to lại một lần không phải bước củng cố hiểu chính.', 'Sai — không nên quên ngay sau khi đọc.', 'Đúng — sau khi đọc nên tóm tắt ý chính để củng cố hiểu.', 'Sai — dịch lại không phải bước củng cố hiểu hiệu quả.']),
  ]),

  M(31, 'Writing skill — Paragraph organization', [
    Q('A good paragraph has?', ['Only questions', 'Many unrelated ideas', 'One main idea with supporting details', 'Only commands'], 2, 'Một ý chính + chi tiết hỗ trợ.', ['Sai — đoạn văn tốt không chỉ gồm câu hỏi.', 'Sai — nhiều ý rời rạc không tạo nên đoạn văn mạch lạc.', 'Đúng — đoạn văn tốt có một ý chính kèm các chi tiết hỗ trợ.', 'Sai — đoạn văn tốt không chỉ gồm câu mệnh lệnh.']),
    Q('A topic sentence states?', ['A question', 'A joke', 'An order', 'The main idea of the paragraph'], 3, 'Câu chủ đề.', ['Sai — câu chủ đề không phải là một câu hỏi.', 'Sai — câu chủ đề không phải là một câu đùa.', 'Sai — câu chủ đề không phải là một câu ra lệnh.', 'Đúng — câu chủ đề nêu ý chính của đoạn văn.']),
    Q('Supporting sentences provide?', ['Examples, reasons, details', 'New topics', 'Translations', 'Unrelated information'], 0, 'Phát triển ý chủ đề.', ['Đúng — câu hỗ trợ cung cấp ví dụ, lý do, chi tiết để phát triển ý chính.', 'Sai — câu hỗ trợ không nêu chủ đề mới.', 'Sai — câu hỗ trợ không phải bản dịch.', 'Sai — câu hỗ trợ không nêu thông tin rời rạc không liên quan.']),
    Q('Concluding sentence does what?', ['Introduces a new topic', 'Asks an unrelated question', 'Repeats the topic sentence exactly', 'Restates the main idea or gives a final thought'], 3, 'Kết câu chủ đề.', ['Sai — câu kết không giới thiệu chủ đề mới.', 'Sai — câu kết không đặt câu hỏi không liên quan.', 'Sai — câu kết không lặp lại y nguyên câu chủ đề.', 'Đúng — câu kết nhắc lại ý chính hoặc đưa ra suy nghĩ kết thúc.']),
    Q('Linking words include?', ['Apple, orange, banana', 'Big, small, tall', 'First, then, finally, however', 'Run, jump, swim'], 2, 'Từ nối.', ['Sai — apple, orange, banana là danh từ trái cây, không phải từ nối.', 'Sai — big, small, tall là tính từ, không phải từ nối.', 'Đúng — first, then, finally, however là các từ nối.', 'Sai — run, jump, swim là động từ, không phải từ nối.']),
    Q('Before writing, you should?', ['Copy from a friend', 'Start immediately without planning', 'Skip the topic', 'Brainstorm and outline'], 3, 'Lập dàn ý trước.', ['Sai — không nên chép bài của bạn.', 'Sai — không nên viết ngay mà không lập kế hoạch.', 'Sai — không nên bỏ qua chủ đề.', 'Đúng — trước khi viết nên động não và lập dàn ý.']),
  ]),

  M(32, 'Speaking — Giving opinions & agreeing/disagreeing', [
    Q('To give an opinion, you can say?', ['"Hello!"', '"I think…"', '"Thank you!"', '"Yes / No only"'], 1, '"I think…", "In my opinion…".', ['Sai — \'Hello!\' là lời chào, không nêu quan điểm.', 'Đúng — nêu quan điểm dùng \'I think…\' hoặc \'In my opinion…\'.', 'Sai — \'Thank you!\' là lời cảm ơn, không nêu quan điểm.', 'Sai — chỉ trả lời Yes/No không phải cách nêu quan điểm.']),
    Q('To agree, you say?', ['"I agree" / "That\'s right"', '"Sorry"', '"I don\'t think so"', '"No way"'], 0, 'Đồng tình.', ['Đúng — đồng tình nói \'I agree\' / \'That\'s right\'.', 'Sai — \'Sorry\' là xin lỗi, không phải đồng tình.', 'Sai — \'I don\'t think so\' là không đồng tình.', 'Sai — \'No way\' là phản đối mạnh, không phải đồng tình.']),
    Q('To disagree politely?', ['"You are wrong!"', '"No, no, no!"', '"I see your point, but…"', '"Stop!"'], 2, 'Bất đồng lịch sự.', ['Sai — \'You are wrong!\' là phản đối thô lỗ, không lịch sự.', 'Sai — \'No, no, no!\' là phản đối gay gắt, không lịch sự.', 'Đúng — bất đồng lịch sự: \'I see your point, but…\'.', 'Sai — \'Stop!\' là ra lệnh, không phải bất đồng lịch sự.']),
    Q('To ask for opinion?', ['"What do you think?"', '"How old are you?"', '"What time is it?"', '"Where are you?"'], 0, 'Hỏi quan điểm.', ['Đúng — hỏi quan điểm: \'What do you think?\'.', 'Sai — \'How old are you?\' hỏi tuổi, không hỏi quan điểm.', 'Sai — \'What time is it?\' hỏi giờ, không hỏi quan điểm.', 'Sai — \'Where are you?\' hỏi nơi chốn, không hỏi quan điểm.']),
    Q('When speaking, eye contact is?', ['Important and polite', 'Aggressive (Hung hăng — gây khó chịu)', 'Unnecessary', 'Forbidden'], 0, 'Giao tiếp mắt là lịch sự.', ['Đúng — giao tiếp bằng mắt là quan trọng và lịch sự khi nói.', 'Sai — giao tiếp bằng mắt phù hợp không phải hung hăng.', 'Sai — giao tiếp bằng mắt là cần thiết, không phải không cần.', 'Sai — giao tiếp bằng mắt không bị cấm khi nói.']),
    Q('To buy time while thinking, say?', ['"Goodbye!"', '"Well…", "Let me think…"', '"Hello!"', '"Thank you!"'], 1, 'Filler phrases.', ['Sai — \'Goodbye!\' là lời tạm biệt, không dùng để câu giờ suy nghĩ.', 'Đúng — câu giờ khi suy nghĩ dùng \'Well…\', \'Let me think…\'.', 'Sai — \'Hello!\' là lời chào, không dùng để câu giờ.', 'Sai — \'Thank you!\' là lời cảm ơn, không dùng để câu giờ.']),
  ]),

  M(33, 'Listening — Predicting & note-taking', [
    Q('Before listening, you should?', ['Read questions and predict answers', 'Translate the title', 'Memorise the whole script (Học thuộc toàn bộ kịch bản)', 'Close your eyes'], 0, 'Dự đoán nội dung.', ['Đúng — trước khi nghe nên đọc câu hỏi và dự đoán câu trả lời.', 'Sai — không cần dịch tiêu đề trước khi nghe.', 'Sai — không thể học thuộc toàn bộ kịch bản trước khi nghe.', 'Sai — nhắm mắt không phải chiến lược nghe hiệu quả.']),
    Q('Key words help you?', ['Confuse you', 'Slow you down', 'Distract you', 'Focus on important information'], 3, 'Tập trung từ khoá.', ['Sai — từ khóa giúp ích chứ không gây rối.', 'Sai — từ khóa không làm bạn chậm lại.', 'Sai — từ khóa không gây xao nhãng.', 'Đúng — từ khóa giúp tập trung vào thông tin quan trọng.']),
    Q('When taking notes, use?', ['Pictures only', 'Full sentences', 'Abbreviations and symbols', 'No words'], 2, 'Viết tắt nhanh.', ['Sai — ghi chú không chỉ dùng hình ảnh.', 'Sai — viết câu đầy đủ thì không kịp khi nghe.', 'Đúng — khi ghi chú nên dùng chữ viết tắt và ký hiệu cho nhanh.', 'Sai — ghi chú vẫn cần dùng chữ, không thể không có từ nào.']),
    Q('If you don\'t understand a word, you should?', ['Write down every word (Viết lại mọi từ — không kịp)', 'Stop completely', 'Translate every word', 'Keep listening for context'], 3, 'Đoán qua ngữ cảnh.', ['Sai — viết lại mọi từ thì không theo kịp bài nghe.', 'Sai — không nên dừng hẳn việc nghe.', 'Sai — không nên dịch từng từ khi đang nghe.', 'Đúng — nên nghe tiếp để đoán nghĩa qua ngữ cảnh.']),
    Q('After listening, you should?', ['Listen again forever', 'Throw notes away', 'Check your answers and reflect', 'Forget immediately'], 2, 'Kiểm tra và phản hồi.', ['Sai — không cần nghe lại mãi mãi.', 'Sai — không nên vứt bỏ ghi chú.', 'Đúng — sau khi nghe nên kiểm tra câu trả lời và rút kinh nghiệm.', 'Sai — không nên quên ngay sau khi nghe.']),
    Q('Listening for gist means?', ['Listening for the general idea', 'Memorizing every word', 'Listening for every detail', 'Counting words'], 0, 'Hiểu ý chính.', ['Đúng — listening for gist là nghe để nắm ý chính tổng quát.', 'Sai — không phải học thuộc từng từ.', 'Sai — nghe từng chi tiết là listening for detail, không phải gist.', 'Sai — đếm từ không phải nghe lấy ý chính.']),
  ]),

  M(34, 'Grammar review — All tenses', [
    Q('"She ___ tennis every Sunday." (play)', ['is playing', 'played', 'has played', 'plays'], 3, 'Habit → present simple, 3rd → plays.', ['Sai — \'is playing\' là tiếp diễn, không hợp thói quen \'every Sunday\'.', 'Sai — \'played\' là quá khứ, không hợp thói quen hiện tại.', 'Sai — \'has played\' là hiện tại hoàn thành, không hợp thói quen lặp lại.', 'Đúng — \'every Sunday\' báo thói quen → hiện tại đơn ngôi 3: plays.']),
    Q('"They ___ a film right now." (watch)', ['are watching', 'watched', 'will watch', 'watch (hiện tại đơn, không hợp \'right now\')'], 0, 'Right now → present continuous.', ['Đúng — \'right now\' báo hành động đang xảy ra → are watching.', 'Sai — \'watched\' là quá khứ, không hợp \'right now\'.', 'Sai — \'will watch\' là tương lai, không hợp \'right now\'.', 'Sai — \'watch\' là hiện tại đơn, không hợp \'right now\'.']),
    Q('"We ___ to Da Nang last summer." (go)', ['have gone', 'go (hiện tại đơn, sai vì có \'last summer\')', 'went', 'are going'], 2, 'Last summer → past simple.', ['Sai — \'have gone\' là hiện tại hoàn thành, không đi với \'last summer\'.', 'Sai — \'go\' là hiện tại đơn, không hợp \'last summer\'.', 'Đúng — \'last summer\' báo quá khứ → went (V2 của go).', 'Sai — \'are going\' là tiếp diễn, không hợp \'last summer\'.']),
    Q('"I ___ never ___ to Japan." (be)', ['will / be', 'do / be', 'have / been', 'did / be'], 2, 'Never → present perfect.', ['Sai — \'will / be\' là tương lai, không đi với \'never\' (kinh nghiệm).', 'Sai — \'do / be\' là hiện tại đơn, không đi với \'never been\'.', 'Đúng — \'never\' chỉ kinh nghiệm → hiện tại hoàn thành: have never been.', 'Sai — \'did / be\' là quá khứ và sai dạng (cần V3 been).']),
    Q('"Tomorrow, I ___ a new car." (buy, plan)', ['will buy', 'bought', 'am buying', 'am going to buy'], 3, 'Plan → going to.', ['Sai — đây là kế hoạch có dự định nên dùng going to thay vì will.', 'Sai — \'bought\' là quá khứ, ngược với \'Tomorrow\'.', 'Sai — \'am buying\' là tiếp diễn, không nhấn ý kế hoạch bằng going to.', 'Đúng — kế hoạch/dự định tương lai: am going to buy.']),
    Q('"If you study hard, you ___ pass." (cond. 1)', ['have (trợ động từ hoàn thành, sai cấu trúc)', 'would (loại 2, không phải loại 1)', 'are (be, không phải tương lai đơn)', 'will'], 3, 'Cond. 1: if + present, will + V.', ['Sai — \'have\' là trợ động từ hoàn thành, sai cấu trúc điều kiện loại 1.', 'Sai — \'would\' dùng cho điều kiện loại 2, không phải loại 1.', 'Sai — \'are\' là be, không tạo tương lai đơn với \'pass\'.', 'Đúng — mệnh đề chính điều kiện loại 1: will + V (will pass).']),
  ]),

  M(35, 'Final exam HK2 — Mixed', [
    Q('Choose the correct passive: "English ___ in many countries."', ['speaks', 'is spoken', 'spoke (quá khứ chủ động, không phải bị động hiện tại)', 'was spoken'], 1, 'Present passive.', ['Sai — \'speaks\' là chủ động, không phải bị động.', 'Đúng — bị động hiện tại đơn: English is spoken.', 'Sai — \'spoke\' là quá khứ chủ động, không phải bị động hiện tại.', 'Sai — \'was spoken\' là bị động quá khứ, không hợp ý hiện tại.']),
    Q('Conditional: "If it rains, we ___ stay home."', ['do (trợ động từ hiện tại, không phải tương lai)', 'would (loại 2, không phải loại 1 thực tế)', 'will', 'have (trợ động từ hoàn thành, sai cấu trúc)'], 2, 'Cond. 1.', ['Sai — \'do\' là trợ động từ hiện tại, không phải tương lai.', 'Sai — \'would\' dùng cho điều kiện loại 2, không phải loại 1.', 'Đúng — mệnh đề chính điều kiện loại 1: will + V (will stay).', 'Sai — \'have\' là trợ động từ hoàn thành, sai cấu trúc loại 1.']),
    Q('"I have ___ him since 2020." (know)', ['knowing', 'know (nguyên mẫu, sai sau \'have\')', 'knew (quá khứ đơn V2, sai sau \'have\')', 'known'], 3, 'Present perfect: known.', ['Sai — \'knowing\' là V-ing, không dùng sau have trong hiện tại hoàn thành.', 'Sai — sau \'have\' dùng V3, không dùng nguyên mẫu know.', 'Sai — \'knew\' là V2 (quá khứ đơn), sau have phải là V3.', 'Đúng — hiện tại hoàn thành với since: have known (V3).']),
    Q('"They ___ to the party last night." (go)', ['have gone', 'go (hiện tại đơn, sai vì có \'last night\')', 'went', 'going (V-ing, thiếu trợ động từ)'], 2, 'Last night → past.', ['Sai — \'have gone\' là hiện tại hoàn thành, không đi với \'last night\'.', 'Sai — \'go\' là hiện tại đơn, không hợp \'last night\'.', 'Đúng — \'last night\' báo quá khứ → went (V2 của go).', 'Sai — \'going\' là V-ing, thiếu trợ động từ và sai thì.']),
    Q('"___ you ___ to England?" (ever / be)', ['Are / been', 'Have / been', 'Do / be', 'Did / be'], 1, 'Ever → present perfect.', ['Sai — \'Are\' không tạo hiện tại hoàn thành dù \'been\' đúng.', 'Đúng — \'ever\' → hiện tại hoàn thành: Have you ever been...?', 'Sai — \'Do / be\' là hiện tại đơn và sai dạng động từ.', 'Sai — \'Did / be\' là quá khứ và sai dạng (cần V3 been).']),
    Q('Comparative of "interesting"?', ['more interesting', 'interestinger', 'interestingest', 'most interesting'], 0, 'Adj dài → more.', ['Đúng — tính từ dài so sánh hơn dùng more + adj: more interesting.', 'Sai — tính từ dài không thêm -er (sai: interestinger).', 'Sai — tính từ dài không thêm -est, và đó là so sánh nhất sai.', 'Sai — \'most interesting\' là so sánh nhất (thiếu the), không phải so sánh hơn.']),
  ]),
];

export const S7TA_SCENARIOS = indexBy(S7TA_WEEKS);
